  DocumentLineItem,
  PurchaseDocumentType,
} from "@/types/documents";
import {
  INDIAN_STATES_AND_CODES,
  PAYMENT_TERMS_SUGGESTIONS,
} from "@/utils/suggestionData";
import { documentsService } from "@/services/documentsService";
