}

import { useRef, useState, useEffect } from "react";
import { createPortal } from "react-dom";
import { CartItem } from "@/types/pos";
import { Printer, X, CheckCircle2, FileText, ScrollText, Smartphone, Copy, Check, Zap, Download, Bluetooth, Sparkles } from "lucide-react";
import { toast } from "@/hooks/use-toast";
import { buildReceiptEscPos, printViaWebUSB, printViaWebBluetooth } from "@/utils/escpos";
import { UnifiedInvoiceRenderer, UniversalDocType, InvoiceItemData } from "@/components/invoices/UnifiedInvoiceRenderer";
import { loadInvoiceSettings } from "@/utils/invoiceThemeLoader";
import { shareInvoicePdfToWhatsApp, downloadInvoicePdf } from "@/utils/whatsappPdfShare";
import { cn } from "@/lib/utils";

export interface ReceiptData {
  invoiceNumber: string;
  referenceNumber?: string;
  docType?: UniversalDocType;
  items: (CartItem | { product: { name: string; brand?: string; category?: string; description?: string; unit?: string; hsn?: string; hsnCode?: string; gstRate?: number }; quantity: number; batch: { mrp: number; batchNumber?: string; expiryDate?: string; costPrice?: number } })[];
  subtotal: number;
  discountAmount: number;
  discountLabel: string;
  tax: number;
  total: number;
  roundOff?: number;
  creditApplied?: number;
  customerName?: string | null;
  customerPhone?: string | null;
  partyEmail?: string | null;
  partyAddress?: string | null;
  partyGstin?: string | null;
  partyBalance?: number | null;
  paymentMethod: string;
  splitPayments?: { cash: number; card: number; upi: number; credit?: number } | null;
  storeName: string;
  storeAddress?: string;
  storePhone?: string;
  storeEmail?: string;
  storeLogoUrl?: string;
  gstin?: string;
  upiId?: string;
  bankName?: string;
  accountNumber?: string;
  ifsc?: string;
  accountHolder?: string;
  branch?: string;
  date: Date | string;
  dueDate?: string;
  isEstimate?: boolean;
  notes?: string;
  terms?: string;
}

interface ReceiptModalProps {
  data: ReceiptData;
  onClose: () => void;
  onNewSale: () => void;
}

export function ReceiptModal({ data, onClose, onNewSale }: ReceiptModalProps) {
  const receiptRef = useRef<HTMLDivElement>(null);
  const scrollBodyRef = useRef<HTMLDivElement>(null);
  const [layout, setLayout] = useState<"80mm" | "58mm" | "a4">("80mm");
  const [copied, setCopied] = useState(false);

  useEffect(() => {
    scrollBodyRef.current?.scrollTo({ top: 0, left: 0, behavior: "instant" });
    if (scrollBodyRef.current) scrollBodyRef.current.scrollTop = 0;
  }, [layout]);

  const receiptDate = data.date instanceof Date ? data.date : new Date(data.date || Date.now());

  // Format date and time
  const formattedDate = receiptDate.toLocaleDateString("en-IN", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  });
  const formattedTime = receiptDate.toLocaleTimeString("en-IN", {
    hour: "2-digit",
    minute: "2-digit",
  });

  // Calculate exact total and round-off
  const exactTotal = data.subtotal - data.discountAmount + data.tax - (data.creditApplied || 0);
  const roundOffAmount = data.roundOff !== undefined ? data.roundOff : Number((data.total - exactTotal).toFixed(2));

  // Tax splitting (CGST = 50%, SGST = 50% of total tax)
  const cgst = data.tax / 2;
  const sgst = data.tax / 2;

  const storeName = data.storeName || "CredSmart Retail Store";
  const storeAddress = data.storeAddress || "";
  const storePhone = data.storePhone || "";
  const gstin = data.gstin || "";

  const handleEscPosPrint = async (directUsb = false) => {
    try {
      const printerWidth = layout === "58mm" ? "58mm" : "80mm";
      const bytes = buildReceiptEscPos(data, {
        width: printerWidth,
        openCashDrawer: data.paymentMethod === "Cash",
        cut: true,
        printQr: true,
        printBarcode: true,
      });

      if (directUsb && "usb" in navigator) {
        toast({ title: "Connecting USB Printer...", description: "Please select your thermal printer from device list." });
        const res = await printViaWebUSB(bytes);
        if (res.success) {
          toast({ title: "ΓÜí Thermal Receipt Printed", description: `Sent raw ESC/POS bytes to printer (${printerWidth}).` });
          return;
        } else {
          toast({ title: "USB Print Notice", description: res.error || "WebUSB transfer failed, downloading raw file.", variant: "destructive" });
        }
      }

      // Default: Download raw binary file or prompt
      const blob = new Blob([bytes], { type: "application/octet-stream" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `receipt_${data.invoiceNumber}_${printerWidth}.bin`;
      document.body.appendChild(a);
      a.click();
      setTimeout(() => {
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
      }, 200);

      toast({
        title: "ΓÜí ESC/POS Payload Generated",
        description: `Downloaded ${printerWidth} raw binary stream (${bytes.length} bytes) for thermal printer.`,
      });
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      toast({ title: "ESC/POS Generation Error", description: message, variant: "destructive" });
    }
  };

  const handlePrint = () => {
    const content = receiptRef.current;
    if (!content) return;

    const printWindow = window.open("", "_blank", "width=850,height=950");
    if (!printWindow) {
      toast({
        title: "Pop-up Blocked",
        description: "Please allow pop-ups for this site to print receipts.",
        variant: "destructive",
      });
      return;
    }

    // Grab all stylesheet links and style tags from current document so all Tailwind & theme styling applies 1:1
    const headStyles = Array.from(document.querySelectorAll("link[rel='stylesheet'], style"))
      .map((el) => el.outerHTML)
      .join("\n");

    let printSpecificStyles = "";

    if (layout === "58mm") {
      printSpecificStyles = `
        @page { margin: 0; size: 58mm auto; }
        * { margin: 0; padding: 0; box-sizing: border-box; -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; }
        html, body {
          font-family: 'Courier New', Courier, monospace;
          width: 56mm;
          max-width: 56mm;
          margin: 0 auto;
          padding: 2mm;
          font-size: 10px;
          color: #000;
          background: #fff;
        }
      `;
    } else if (layout === "80mm") {
      printSpecificStyles = `
        @page { margin: 0; size: 80mm auto; }
        * { margin: 0; padding: 0; box-sizing: border-box; -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; }
        html, body {
          font-family: 'Courier New', Courier, monospace;
          width: 76mm;
          max-width: 76mm;
          margin: 0 auto;
          padding: 3mm;
          font-size: 11px;
          color: #000;
          background: #fff;
        }
      `;
    } else {
      printSpecificStyles = `
        @page {
          size: A4 portrait;
          margin: 5mm 7mm;
        }
        * {
          -webkit-print-color-adjust: exact !important;
          print-color-adjust: exact !important;
          box-sizing: border-box !important;
        }
        html, body {
          width: 100% !important;
          height: auto !important;
          margin: 0 !important;
          padding: 0 !important;
          background: #fff !important;
          font-size: 10px !important;
          line-height: 1.25 !important;
        }
        #unified-invoice-document {
          width: 100% !important;
          max-width: 100% !important;
          min-width: 0 !important;
          box-shadow: none !important;
          border: 1px solid #e2e8f0 !important;
          border-radius: 0 !important;
          padding: 0 !important;
          margin: 0 auto !important;
          page-break-after: avoid !important;
          page-break-inside: avoid !important;
          break-inside: avoid !important;
        }
      `;
    }

    printWindow.document.open();
    printWindow.document.write(`
      <!DOCTYPE html>
      <html lang="en">
      <head>
        <meta charset="utf-8">
        <title>Invoice - ${data.invoiceNumber}</title>
        ${headStyles}
        <style>${printSpecificStyles}</style>
      </head>
      <body class="bg-white p-0 m-0">
        <div class="w-full flex justify-center">
          ${content.outerHTML}
        </div>
        <script>
          window.onload = function() {
            setTimeout(function() {
              window.focus();
              window.print();
              window.close();
            }, 300);
          };
        </script>
      </body>
      </html>
    `);
    printWindow.document.close();
  };

  const handleWhatsApp = async () => {
    await shareInvoicePdfToWhatsApp({
      invoiceNumber: data.invoiceNumber,
      customerName: data.customerName || undefined,
      customerPhone: data.customerPhone || undefined,
      storeName: storeName,
      storePhone: storePhone || undefined,
      totalAmount: data.total,
      date: formattedDate,
      isEstimate: data.isEstimate,
      elementId: "receipt-printable-area",
      items: data.items.map((it) => ({
        name: it.product.name,
        quantity: it.quantity,
        rate: it.batch.mrp,
        total: it.batch.mrp * it.quantity,
      })),
    });
  };

  const handleDownload = async () => {
    await downloadInvoicePdf({
      invoiceNumber: data.invoiceNumber,
      customerName: data.customerName || undefined,
      customerPhone: data.customerPhone || undefined,
      storeName: storeName,
      storePhone: storePhone || undefined,
      totalAmount: data.total,
      date: formattedDate,
      isEstimate: data.isEstimate,
      elementId: "receipt-printable-area",
      items: data.items.map((it) => ({
        name: (it as any).product?.name || (it as any).name || "Item",
        quantity: it.quantity,
        rate: (it as any).batch?.mrp || (it as any).rate || (it as any).unitPrice || 0,
        total: ((it as any).batch?.mrp || (it as any).rate || (it as any).unitPrice || 0) * it.quantity,
      })),
    });
  };

  const handleCopySummary = () => {
    const summary = `${data.isEstimate ? "Estimate" : "Invoice"}: ${data.invoiceNumber} | Store: ${storeName} | Total: Γé╣${data.total.toFixed(2)} | Date: ${formattedDate}`;
    navigator.clipboard.writeText(summary);
    setCopied(true);
    toast({ title: "Invoice Summary Copied", description: summary });
    setTimeout(() => setCopied(false), 2000);
  };

  return createPortal(
    <div
      role="dialog"
      aria-modal="true"
      aria-labelledby="receipt-modal-title"
      className="fixed inset-0 z-[99999] flex flex-col items-center justify-center bg-black/85 backdrop-blur-md p-0 sm:p-4 pb-[env(safe-area-inset-bottom,0px)]"
    >
      <div className="bg-slate-900 border-0 sm:border border-slate-800 w-full h-[100dvh] sm:h-auto max-h-[100dvh] sm:max-h-[94vh] max-w-full sm:max-w-[780px] sm:rounded-3xl flex flex-col shadow-2xl text-white overflow-hidden animate-scale-in">

        {/* Header */}
        <div className="flex items-center justify-between px-3.5 sm:px-6 py-3 sm:py-3.5 border-b border-slate-800 bg-slate-900/95 shrink-0 z-10">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 rounded-xl bg-emerald-500/15 text-emerald-400 border border-emerald-500/30 flex items-center justify-center shadow-xs">
              <CheckCircle2 className="w-5 h-5" />
            </div>
            <div>
              <h2 className="font-bold text-white text-sm sm:text-base flex items-center gap-2">
                <span>{data.isEstimate ? "Estimate Generated" : "Bill Saved Successfully"}</span>
                <span className="text-[10px] font-mono font-semibold bg-emerald-500/20 text-emerald-300 px-2 py-0.5 rounded-full border border-emerald-500/30">
                  Γé╣{data.total.toLocaleString("en-IN")}
                </span>
              </h2>
              <p className="text-[11px] text-slate-400 font-mono">Invoice #{data.invoiceNumber}</p>
            </div>
          </div>

          <div className="flex items-center gap-2">
            {/* Format Segment Switcher */}
            <div className="flex bg-slate-950 p-0.5 sm:p-1 rounded-xl border border-slate-800 shrink-0">
              <button
                type="button"
                onClick={() => setLayout("80mm")}
                className={cn(
                  "px-2 sm:px-3 py-1 rounded-lg text-[10px] sm:text-xs font-bold flex items-center gap-1 sm:gap-1.5 transition-all",
                  layout === "80mm"
                    ? "bg-indigo-600 text-white shadow-sm shadow-indigo-600/30"
                    : "text-slate-400 hover:text-slate-200"
                )}
              >
                <ScrollText className="w-3 sm:w-3.5 h-3 sm:h-3.5" />
                <span>80mm</span>
              </button>
              <button
                type="button"
                onClick={() => setLayout("58mm")}
                className={cn(
                  "px-2 sm:px-3 py-1 rounded-lg text-[10px] sm:text-xs font-bold flex items-center gap-1 sm:gap-1.5 transition-all",
                  layout === "58mm"
                    ? "bg-indigo-600 text-white shadow-sm shadow-indigo-600/30"
                    : "text-slate-400 hover:text-slate-200"
                )}
              >
                <Smartphone className="w-3 sm:w-3.5 h-3 sm:h-3.5" />
                <span>58mm</span>
              </button>
              <button
                type="button"
                onClick={() => setLayout("a4")}
                className={cn(
                  "px-2 sm:px-3 py-1 rounded-lg text-[10px] sm:text-xs font-bold flex items-center gap-1 sm:gap-1.5 transition-all",
                  layout === "a4"
                    ? "bg-indigo-600 text-white shadow-sm shadow-indigo-600/30"
                    : "text-slate-400 hover:text-slate-200"
                )}
              >
                <FileText className="w-3 sm:w-3.5 h-3 sm:h-3.5" />
                <span>A4</span>
              </button>
            </div>

            <button
              type="button"
              onClick={onClose}
              className="w-8 h-8 rounded-xl flex items-center justify-center hover:bg-slate-800 text-slate-400 hover:text-white transition-colors"
              aria-label="Close invoice preview"
            >
              <X className="w-4 h-4" />
            </button>
          </div>
        </div>

        {/* Receipt Preview Body with Thermal Paper Styling */}
        <div ref={scrollBodyRef} className="flex-1 overflow-y-auto p-4 sm:p-6 bg-slate-950 flex justify-center items-start">
          <div className="bg-white rounded-2xl shadow-2xl overflow-hidden p-1 text-slate-900 border border-slate-200">
            <UnifiedInvoiceRenderer
              ref={receiptRef}
              layout={layout}
              docType={data.docType || (data.isEstimate ? "quotation" : "sales_invoice")}
              invoiceNumber={data.invoiceNumber}
              referenceNumber={data.referenceNumber}
              date={data.date}
              dueDate={data.dueDate}
              storeInfo={{
                name: storeName,
                address: storeAddress,
                phone: storePhone,
                email: data.storeEmail || "billing@credsmart.in",
                gstin: gstin,
                logoUrl: data.storeLogoUrl || "",
              }}
              partyInfo={{
                name: data.customerName || (data.docType === "purchase_invoice" ? "Vendor" : "Walk-in Customer"),
                phone: data.customerPhone,
                email: data.partyEmail,
                address: data.partyAddress,
                gstin: data.partyGstin,
                balance: data.partyBalance,
                type: data.docType === "purchase_invoice" || data.docType === "debit_note" ? "supplier" : "customer",
              }}
              items={data.items.map((item, idx) => {
                const itemData = item as {
                  product?: {
                    name?: string;
                    description?: string;
                    brand?: string;
                    category?: string;
                    hsn?: string;
                    hsnCode?: string;
                    gstRate?: number;
                    unit?: string;
                  } | null;
                  batch?: {
                    mrp?: number;
                    batchNumber?: string;
                    expiryDate?: string;
                  } | null;
                  rate?: number;
                  unitPrice?: number;
                  name?: string;
                  hsn?: string;
                  unit?: string;
                  altUnit?: string;
                  altQty?: number;
                  altUnitConversion?: number;
                  taxRate?: number;
                  batchNo?: string;
                  expDate?: string;
                };
                const p = itemData.product ?? {};
                const b = itemData.batch ?? {};
                const qty = Number(item.quantity) || 1;
                const rate = Number(b.mrp ?? itemData.rate ?? itemData.unitPrice ?? 0);
                const resolvedUnit = itemData.unit || p.unit || "PCS";
                const resolvedAltUnit = itemData.altUnit || p.altUnit || p.tags?.alt_unit || undefined;
                const resolvedAltConv = itemData.altUnitConversion ?? p.altUnitConversion ?? p.tags?.alt_unit_conversion ?? undefined;
                const resolvedAltQty = itemData.altQty !== undefined
                  ? itemData.altQty
                  : (resolvedAltUnit && resolvedAltConv && Number(resolvedAltConv) > 1 && resolvedUnit.toUpperCase() === resolvedAltUnit.toUpperCase() ? qty : undefined);

                return {
                  id: String(idx),
                  name: p.name ?? itemData.name ?? `Item ${idx + 1}`,
                  description: p.description ?? (p.brand ? `${p.brand} ┬╖ ${p.category || ""}` : ""),
                  hsn: p.hsn ?? p.hsnCode ?? itemData.hsn ?? "",
                  qty,
                  unit: resolvedUnit,
                  altUnit: resolvedAltUnit,
                  altQty: resolvedAltQty,
                  altUnitConversion: resolvedAltConv ? Number(resolvedAltConv) : undefined,
                  rate,
                  mrp: rate,
                  discount: 0,
                  taxRate: p.gstRate ?? itemData.taxRate ?? 0,
                  total: rate * qty,
                  batchNo: b.batchNumber ?? itemData.batchNo ?? "",
                  expDate: b.expiryDate ?? itemData.expDate ?? "",
                };
              })}
              totals={{
                subtotal: data.subtotal,
                discountTotal: data.discountAmount,
                discountLabel: data.discountLabel,
                taxableAmount: data.subtotal - data.discountAmount,
                cgst: cgst,
                sgst: sgst,
                taxTotal: data.tax,
                roundOff: roundOffAmount,
                grandTotal: data.total,
                paidAmount: data.paymentMethod === "Credit" ? 0 : data.total,
                balanceDue: data.paymentMethod === "Credit" ? data.total : 0,
              }}
              paymentMethod={data.paymentMethod}
              notes={data.notes}
              terms={data.terms}
            />
          </div>
        </div>

        {/* Modal Action Bar: Clean 3-Action Footer (Print, Download, Whatsapp) */}
        <div className="px-3.5 sm:px-6 py-3 sm:py-4 border-t border-slate-800 grid grid-cols-3 gap-2.5 sm:gap-3 bg-slate-900 sm:rounded-b-3xl shrink-0 z-10 pb-[max(0.75rem,env(safe-area-inset-bottom,0px))]">
          {/* 1. Print */}
          <button
            type="button"
            onClick={handlePrint}
            className="flex items-center justify-center gap-2 py-3 px-3 rounded-xl bg-indigo-600 hover:bg-indigo-500 text-white font-bold text-xs sm:text-sm transition-all shadow-md shadow-indigo-950/40 active:scale-95 cursor-pointer"
          >
            <Printer className="w-4 h-4 shrink-0" />
            <span>Print</span>
          </button>

          {/* 2. Download */}
          <button
            type="button"
            onClick={handleDownload}
            className="flex items-center justify-center gap-2 py-3 px-3 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-100 hover:text-white font-bold text-xs sm:text-sm transition-all border border-slate-700 active:scale-95 cursor-pointer shadow-md"
          >
            <Download className="w-4 h-4 shrink-0 text-amber-400" />
            <span>Download</span>
          </button>

          {/* 3. Whatsapp */}
          <button
            type="button"
            onClick={handleWhatsApp}
            className="flex items-center justify-center gap-2 py-3 px-3 rounded-xl bg-emerald-600 hover:bg-emerald-500 text-white font-bold text-xs sm:text-sm transition-all shadow-md shadow-emerald-950/40 active:scale-95 cursor-pointer"
          >
            <svg viewBox="0 0 24 24" className="w-4 h-4 fill-current shrink-0" xmlns="http://www.w3.org/2000/svg">
              <path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.888-.788-1.489-1.761-1.663-2.06-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51a12.8 12.8 0 0 0-.57-.01c-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 0 1-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 0 1-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 0 1 2.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0 0 12.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 0 0 5.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 0 0-3.48-8.413Z"/>
            </svg>
            <span>Whatsapp</span>
          </button>
        </div>
      </div>
    </div>,
    document.body
  );
}

import { useState, useEffect, useMemo, useRef } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Checkbox } from "@/components/ui/checkbox";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Plus,
  Trash2,
  Save,
  Printer,
  FileText,
  UserPlus,
  ArrowLeft,
  Settings,
  ScanBarcode,
  Building2,
  Calendar as CalendarIcon,
  RotateCcw,
  QrCode,
  Edit3,
  HelpCircle,
  ChevronDown,
  ChevronUp,
  Eye,
  Package,
  Sparkles,
} from "lucide-react";
import { QRCodeSVG } from "qrcode.react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { useOrganization } from "@/hooks/useOrganization";
import { toast } from "sonner";
import {
  BusinessDocument,
  DocumentLineItem,
  SalesDocumentType,
} from "@/types/documents";
import {
  INDIAN_STATES_AND_CODES,
  PAYMENT_TERMS_SUGGESTIONS,
} from "@/utils/suggestionData";
import { documentsService } from "@/services/documentsService";
import { cn } from "@/lib/utils";
import { UnifiedInvoiceRenderer } from "@/components/invoices/UnifiedInvoiceRenderer";
import { AddItemsToBillModal, BillItemOption } from "@/components/invoices/AddItemsToBillModal";
import { useProducts } from "@/context/ProductsContext";
import { networkInvoicingService } from "@/services/networkInvoicingService";
import { ConnectedOrgInfo } from "@/types/networkInvoicing";
import { PartyCustomItem } from "@/types/parties";
import { QuickCreateItemModal, CreatedProductResult } from "@/components/items/QuickCreateItemModal";

interface CustomerOption {
  id: string;
  name: string;
  phone: string;
  email?: string;
  gstin?: string;
  address?: string;
  balance?: number;
  custom_fields?: Record<string, any>;
  keepSamePrice?: boolean;
  keepSameInventory?: boolean;
  customItems?: PartyCustomItem[];
}

interface ProductCatalogOption {
  id: string;
  name: string;
  category?: string;
  barcode: string | null;
  brand: string | null;
  sku?: string;
  unit?: string;
  altUnit?: string;
  altUnitConversion?: number;
  selling_price?: number;
  tax_rate?: number;
  tags?: Record<string, any>;
  product_batches?: {
    id: string;
    batch_number: string;
    mrp: number;
    stock: number;
    expiry_date: string | null;
  }[];
}

interface UnifiedProductSuggestion {
  id: string;
  name: string;
  category: string;
  barcode?: string;
  sku?: string;
  hsn?: string;
  unit: string;
  altUnit?: string;
  altUnitConversion?: number;
  rate: number;
  mrp?: number;
  gstRate: number;
  stock: number;
  batchNumber?: string;
  isDb?: boolean;
}

interface SalesInvoiceModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  orgId: string;
  initialDocType?: SalesDocumentType;
  editingDoc?: BusinessDocument | null;
  onSaved: (doc: BusinessDocument) => void;
  onPrintRequest?: (doc: BusinessDocument) => void;
}

const getErrorMessage = (error: unknown, fallback: string) =>
  error instanceof Error ? error.message : typeof error === "string" ? error : fallback;

export function SalesInvoiceModal({
  open,
  onOpenChange,
  orgId,
  initialDocType = "sales_invoice",
  editingDoc = null,
  onSaved,
  onPrintRequest,
}: SalesInvoiceModalProps) {
  const { user } = useAuth();
  const { org } = useOrganization();

  // Mode: "edit" | "preview"
  const [viewMode, setViewMode] = useState<"edit" | "preview">("edit");

  // Document Type
  const [docType, setDocType] = useState<SalesDocumentType>(initialDocType);

  // Party State
  const [customers, setCustomers] = useState<CustomerOption[]>([]);
  const [selectedCustomerId, setSelectedCustomerId] = useState("");
  const [customerSearch, setCustomerSearch] = useState("");
  const [showCustomerDropdown, setShowCustomerDropdown] = useState(false);
  const [partyName, setPartyName] = useState("");
  const [partyPhone, setPartyPhone] = useState("");
  const [partyGstin, setPartyGstin] = useState("");
  const [partyAddress, setPartyAddress] = useState("");
  const [placeOfSupply, setPlaceOfSupply] = useState("27-Maharashtra");
  const [connectedPartner, setConnectedPartner] = useState<ConnectedOrgInfo | null>(null);

  // Auto-detect if customer is a connected CredSmart partner business
  useEffect(() => {
    let isMounted = true;
    if (!partyName.trim()) {
      setConnectedPartner(null);
      return;
    }
    networkInvoicingService.findConnectedOrganization({
      orgId: selectedCustomerId,
      phone: partyPhone,
      gstin: partyGstin,
      name: partyName,
    }).then((partner) => {
      if (isMounted) {
        if (partner && partner.id !== orgId) {
          setConnectedPartner(partner);
        } else {
          setConnectedPartner(null);
        }
      }
    });
    return () => {
      isMounted = false;
    };
  }, [partyName, partyPhone, partyGstin, selectedCustomerId, orgId]);

  // Billing Address fields (new)
  const [billingAddress, setBillingAddress] = useState("");
  const [billingPincode, setBillingPincode] = useState("");
  const [billingPlaceOfSupply, setBillingPlaceOfSupply] = useState("27-Maharashtra");
  const [sameAsParty, setSameAsParty] = useState(false);

  // Inline New Customer Modal
  const [showNewCustomerDialog, setShowNewCustomerDialog] = useState(false);
  const [newCustName, setNewCustName] = useState("");
  const [newCustPhone, setNewCustPhone] = useState("");
  const [newCustGstin, setNewCustGstin] = useState("");
  const [newCustAddress, setNewCustAddress] = useState("");

  // Invoice Details
  const [invoicePrefix, setInvoicePrefix] = useState("INV/26-27/");
  const [invoiceNumberSeq, setInvoiceNumberSeq] = useState("101");
  const [repeatInvoice, setRepeatInvoice] = useState(false);
  const [docDate, setDocDate] = useState(new Date().toISOString().split("T")[0]);
  const [showDueDate, setShowDueDate] = useState(false);
  const [dueDate, setDueDate] = useState(new Date().toISOString().split("T")[0]);
  const [paymentTerms, setPaymentTerms] = useState("Due on Receipt");
  const [ewayBillNo, setEwayBillNo] = useState("");
  const [vehicleNumber, setVehicleNumber] = useState("");

  // Products catalog & Item search (shared store)
  const { products: productsCatalog, refreshProducts, addOrUpdateProduct } = useProducts();
  const [itemSearchText, setItemSearchText] = useState<Record<number, string>>({});
  const [activeItemDropdown, setActiveItemDropdown] = useState<number | null>(null);
  const [showAddItemsModal, setShowAddItemsModal] = useState(false);

  // Item input refs for auto-focus
  const itemInputRefs = useRef<Record<number, HTMLInputElement | null>>({});
  const focusItemInput = (index: number) => {
    setTimeout(() => {
      itemInputRefs.current[index]?.focus();
    }, 60);
  };

  // Quick Create Item State
  const [showQuickCreateItemModal, setShowQuickCreateItemModal] = useState(false);
  const [targetRowIndexForNewItem, setTargetRowIndexForNewItem] = useState<number | null>(null);
  const [initialNewItemName, setInitialNewItemName] = useState("");
  // When AddItems modal is opened from a specific row, this remembers the row index so
  // selected items can be inserted/handled for that row if needed.
  const [addItemsTargetRow, setAddItemsTargetRow] = useState<number | null>(null);

  const activeCustomer = useMemo(() => {
    return customers.find((c) => c.id === selectedCustomerId) || null;
  }, [customers, selectedCustomerId]);

  const billItemOptions: BillItemOption[] = useMemo(() => {
    let catalog = productsCatalog || [];

    if (activeCustomer && activeCustomer.keepSameInventory === false && activeCustomer.customItems && activeCustomer.customItems.length > 0) {
      const allowedIds = new Set(activeCustomer.customItems.map((ci) => ci.productId));
      catalog = catalog.filter((p) => allowedIds.has(p.id));
    }

    const customPriceMap = new Map<string, number>();
    if (activeCustomer && activeCustomer.keepSamePrice === false && activeCustomer.customItems) {
      activeCustomer.customItems.forEach((ci) => {
        customPriceMap.set(ci.productId, ci.customPrice);
      });
    }

    return catalog.map((p) => {
      const tags = (p as any).tags || {};
      const defaultSelling = tags && (tags.selling_price !== undefined && tags.selling_price !== null)
        ? Number(tags.selling_price)
        : (p.product_batches?.[0]?.mrp || 0);
      const selling = customPriceMap.has(p.id) ? (customPriceMap.get(p.id) ?? defaultSelling) : defaultSelling;
      const gst = tags && (tags.gst_rate !== undefined && tags.gst_rate !== null) ? Number(tags.gst_rate) : 18;
      const hsnVal = tags?.hsn_code || tags?.hsn || (p as any).hsn || undefined;
      const altUnitVal = (p as any).altUnit || tags?.alt_unit || undefined;
      const altConvVal = (p as any).altUnitConversion ?? tags?.alt_unit_conversion ?? undefined;

      return {
        id: p.id,
        name: p.name,
        category: p.category || "General",
        barcode: p.barcode,
        sku: p.sku,
        hsn: hsnVal,
        unit: p.unit || "Pcs",
        altUnit: altUnitVal,
        altUnitConversion: altConvVal ? Number(altConvVal) : undefined,
        sellingPrice: selling,
        gstRate: gst,
        stock: p.product_batches?.reduce((sum, b) => sum + (Number(b.stock) || 0), 0) || 0,
      };
    });
  }, [productsCatalog, activeCustomer]);

  // Line items
  const [items, setItems] = useState<DocumentLineItem[]>([
    {
      id: "row-1",
      productName: "",
      hsn: "",
      quantity: 1,
      unit: "Pcs",
      rate: 0,
      discountPercent: 0,
      discountAmount: 0,
      taxRate: 18,
      taxableAmount: 0,
      cgstAmount: 0,
      sgstAmount: 0,
      igstAmount: 0,
      lineTotal: 0,
    },
  ]);

  // Notes & Terms
  const [showNotes, setShowNotes] = useState(false);
  const [notes, setNotes] = useState("");
  const [termsOpen, setTermsOpen] = useState(true);
  const [terms, setTerms] = useState(
    "1. Goods once sold will not be taken back or exchanged.\n2. All disputes are subject to local jurisdiction only."
  );

  // Bank & UPI QR details
  const [showBankDetails, setShowBankDetails] = useState(true);
  const [bankAccount, setBankAccount] = useState({
    accountNumber: "",
    ifsc: "",
    bankName: "",
    branch: "",
    accountHolder: "",
  });

  const editorBodyRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (open) {
      editorBodyRef.current?.scrollTo({ top: 0, left: 0, behavior: "instant" });
      if (editorBodyRef.current) editorBodyRef.current.scrollTop = 0;
    }
  }, [open, viewMode]);
  const [showPaymentQr, setShowPaymentQr] = useState(true);
  const [upiId, setUpiId] = useState("");

  // Signature & Stamp
  const [showStamp, setShowStamp] = useState(true);
  const [stampUrl, setStampUrl] = useState<string>("");

  // Financial Settlement & Calculations
  const [showAdditionalCharges, setShowAdditionalCharges] = useState(false);
  const [additionalChargesAmount, setAdditionalChargesAmount] = useState<number>(0);
  const [additionalChargesReason, setAdditionalChargesReason] = useState("Delivery / Shipping");

  const [showDiscount, setShowDiscount] = useState(false);
  const [overallDiscountType, setOverallDiscountType] = useState<"flat" | "percent">("flat");
  const [overallDiscountValue, setOverallDiscountValue] = useState<number>(0);

  const [autoRoundOff, setAutoRoundOff] = useState(true);
  const [manualRoundOff, setManualRoundOff] = useState<number>(0);

  const [amountReceived, setAmountReceived] = useState<number>(0);
  const [paymentMethod, setPaymentMethod] = useState("Cash");
  const [markAsFullyPaid, setMarkAsFullyPaid] = useState(false);

  // Loading & Saving
  const [saving, setSaving] = useState(false);

  // Full Document Number Computed
  const fullDocumentNumber = `${invoicePrefix}${invoiceNumberSeq}`.trim();

  // Load Store Settings (Bank, UPI, Stamp) on Mount/Org change
  useEffect(() => {
    if (!orgId) return;
    try {
      const storedSettings = localStorage.getItem(`credsmart_business_settings_${orgId}`);
      if (storedSettings) {
        const parsed = JSON.parse(storedSettings);
        if (parsed.bankAccounts && parsed.bankAccounts.length > 0) {
          const def = parsed.bankAccounts.find((b: { isDefault?: boolean }) => b.isDefault) || parsed.bankAccounts[0];
          setBankAccount({
            accountNumber: def.accountNumber || "",
            ifsc: def.ifsc || "",
            bankName: def.bankName || "",
            branch: def.branch || "",
            accountHolder: def.accountHolder || parsed.businessName || org?.name || "",
          });
        }
        if (parsed.upiId) setUpiId(parsed.upiId);
        if (parsed.signatureUrl) setStampUrl(parsed.signatureUrl);
      } else if (org) {
        if (org.upi_id) setUpiId(org.upi_id);
        if (org.account_number) {
          setBankAccount({
            accountNumber: org.account_number,
            ifsc: org.ifsc || "",
            bankName: org.bank_name || "",
            branch: "",
            accountHolder: org.account_holder || org.name || "",
          });
        }
      }
    } catch (e) {
      console.warn("Could not load business settings in invoice modal:", e);
    }
  }, [orgId, org]);

  // Fetch Customers & Products with Ledger Balances
  const fetchCustomers = async () => {
    if (!orgId) return;
    try {
      const { data: custData } = await supabase
        .from("customers")
        .select("id, name, phone, email, address, custom_fields")
        .eq("organization_id", orgId)
        .order("name");

      const { data: creditData } = await supabase
        .from("credit_transactions")
        .select("party_id, amount, type")
        .eq("organization_id", orgId);

      const balanceMap: Record<string, number> = {};
      (creditData || []).forEach((c) => {
        const amt = Number(c.amount) || 0;
        const curr = balanceMap[c.party_id] || 0;
        if (c.type === "credit") {
          balanceMap[c.party_id] = curr + amt;
        } else if (c.type === "payment") {
          balanceMap[c.party_id] = curr - amt;
        }
      });

      if (custData) {
        const merged = custData.map((c: any) => {
          const cf = typeof c.custom_fields === "object" && c.custom_fields !== null ? c.custom_fields : {};
          const keepSamePrice = cf.keepSamePrice !== false;
          const keepSameInventory = cf.keepSameInventory !== false;
          const customItems = Array.isArray(cf.customItems) ? cf.customItems : [];

          return {
            ...c,
            balance: balanceMap[c.id] || 0,
            custom_fields: cf,
            keepSamePrice,
            keepSameInventory,
            customItems,
          };
        });
        setCustomers(merged);
      }
    } catch (e) {
      console.error(e);
    }
  };

  const fetchProducts = async () => {
    if (!orgId) return;
    try {
      await refreshProducts(orgId);
    } catch (e) {
      console.error(e);
    }
  };

  // Reset or Init Form
  useEffect(() => {
    if (open) {
      fetchCustomers();
      fetchProducts();
      setViewMode("edit");

      if (editingDoc) {
        setDocType(editingDoc.docType as SalesDocumentType);
        const docNum = editingDoc.documentNumber || "";
        const lastSlash = docNum.lastIndexOf("/");
        const lastDash = docNum.lastIndexOf("-");
        const splitIndex = Math.max(lastSlash, lastDash);
        if (splitIndex !== -1) {
          setInvoicePrefix(docNum.substring(0, splitIndex + 1));
          setInvoiceNumberSeq(docNum.substring(splitIndex + 1));
        } else {
          setInvoicePrefix("INV/");
          setInvoiceNumberSeq(docNum);
        }

        setSelectedCustomerId(editingDoc.partyId || "");
        setPartyName(editingDoc.partyName || "");
        setPartyPhone(editingDoc.partyPhone || "");
        setPartyGstin(editingDoc.partyGstin || "");
        setPartyAddress(editingDoc.partyAddress || "");
        // Billing fields from editing document (if available)
        const legacyBillingAddress = editingDoc.billingAddress ?? editingDoc.partyAddress ?? "";
        setBillingAddress(legacyBillingAddress);
        setBillingPincode(editingDoc.billingPincode || "");
        setBillingPlaceOfSupply(editingDoc.billingPlaceOfSupply || editingDoc.placeOfSupply || "27-Maharashtra");
        setSameAsParty(Boolean(editingDoc.partyAddress && legacyBillingAddress === editingDoc.partyAddress));
        setPlaceOfSupply(editingDoc.placeOfSupply || "27-Maharashtra");
        setDocDate(editingDoc.docDate || new Date().toISOString().split("T")[0]);
        if (editingDoc.dueDate) {
          setShowDueDate(true);
          setDueDate(editingDoc.dueDate);
        }
        setPaymentTerms(editingDoc.paymentTerms || "Due on Receipt");
        setItems(editingDoc.items && editingDoc.items.length > 0 ? editingDoc.items : [createNewRow("row-1")]);
        setPaymentMethod(editingDoc.paymentMethod || "Cash");
        setAmountReceived(editingDoc.paidAmount || 0);
        setNotes(editingDoc.notes || "");
        if (editingDoc.notes) setShowNotes(true);
        setTerms(editingDoc.terms || "1. Goods once sold will not be taken back or exchanged.\n2. All disputes are subject to local jurisdiction only.");
        if (editingDoc.transportDetails?.vehicleNumber) {
          setVehicleNumber(editingDoc.transportDetails.vehicleNumber);
        }
      } else {
        const targetType = initialDocType || "sales_invoice";
        setDocType(targetType);
        const randSeq = Math.floor(100 + Math.random() * 900).toString();
        setInvoicePrefix("INV/26-27/");
        setInvoiceNumberSeq(randSeq);
        setSelectedCustomerId("");
        setPartyName("");
        setCustomerSearch("");
        setPartyPhone("");
        setPartyGstin("");
        setPartyAddress("");
        // Reset billing fields for new document
        setBillingAddress("");
        setBillingPincode("");
        setBillingPlaceOfSupply("27-Maharashtra");
        setSameAsParty(false);
        setDocDate(new Date().toISOString().split("T")[0]);
        setShowDueDate(false);
        setEwayBillNo("");
        setVehicleNumber("");
        setNotes("");
        setShowNotes(false);
        setShowAdditionalCharges(false);
        setAdditionalChargesAmount(0);
        setShowDiscount(false);
        setOverallDiscountValue(0);
        setItems([createNewRow("row-1")]);
        setAmountReceived(0);
        setMarkAsFullyPaid(false);
        setPaymentMethod("Cash");
      }
    }
  }, [open, editingDoc, initialDocType]);

  const createNewRow = (id: string): DocumentLineItem => ({
    id,
    productName: "",
    hsn: "",
    quantity: 1,
    unit: "Pcs",
    rate: 0,
    discountPercent: 0,
    discountAmount: 0,
    taxRate: 18,
    taxableAmount: 0,
    cgstAmount: 0,
    sgstAmount: 0,
    igstAmount: 0,
    lineTotal: 0,
  });

  // Direct line adding like POS & auto-focus
  const handleAddRow = () => {
    const newId = `row-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`;
    setItems((prev) => {
      const newIdx = prev.length;
      focusItemInput(newIdx);
      return [...prev, createNewRow(newId)];
    });
  };

  const handleBatchAddItems = (newItems: DocumentLineItem[]) => {
    setItems((prev) => {
      const cleanExisting = prev.filter((it) => it.productName.trim() !== "");
      const combined = [...cleanExisting, ...newItems];
      // Auto add new blank line after every item selection
      const nextId = `row-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`;
      return [...combined, createNewRow(nextId)];
    });
  };

  const handleRemoveRow = (index: number) => {
    if (items.length <= 1) {
      setItems([createNewRow(`row-${Date.now()}`)]);
      return;
    }
    setItems((prev) => prev.filter((_, i) => i !== index));
  };

  // State Code / Interstate
  const orgStateCode = "27"; // Maharashtra
  const isInterState = useMemo(() => {
    const custCode = (placeOfSupply || "").slice(0, 2);
    return custCode !== "" && custCode !== orgStateCode;
  }, [placeOfSupply]);

  // Recalculate Line Items
  const recalculatedItems = useMemo(() => {
    return items.map((item) => {
      const rawSub = (Number(item.quantity) || 0) * (Number(item.rate) || 0);
      const discount = item.discountPercent > 0
        ? (rawSub * item.discountPercent) / 100
        : item.discountAmount || 0;
      const taxable = Math.max(0, rawSub - discount);

      const taxAmount = (taxable * (Number(item.taxRate) || 0)) / 100;
      let cgst = 0;
      let sgst = 0;
      let igst = 0;

      if (isInterState) {
        igst = taxAmount;
      } else {
        cgst = taxAmount / 2;
        sgst = taxAmount / 2;
      }

      const lineTotal = taxable + taxAmount;

      return {
        ...item,
        taxableAmount: Number(taxable.toFixed(2)),
        cgstAmount: Number(cgst.toFixed(2)),
        sgstAmount: Number(sgst.toFixed(2)),
        igstAmount: Number(igst.toFixed(2)),
        lineTotal: Number(lineTotal.toFixed(2)),
      };
    });
  }, [items, isInterState]);

  // Document Grand Totals
  const totals = useMemo(() => {
    const totalQty = recalculatedItems.reduce((acc, it) => acc + (Number(it.quantity) || 0), 0);
    const rawSubtotal = recalculatedItems.reduce((acc, it) => acc + (Number(it.quantity) || 0) * (Number(it.rate) || 0), 0);
    const itemDiscounts = recalculatedItems.reduce((acc, it) => acc + ((Number(it.quantity) || 0) * (Number(it.rate) || 0) - it.taxableAmount), 0);
    const taxableTotal = recalculatedItems.reduce((acc, it) => acc + it.taxableAmount, 0);

    const overallDisc = overallDiscountType === "percent"
      ? (taxableTotal * (overallDiscountValue || 0)) / 100
      : overallDiscountValue || 0;

    const finalTaxable = Math.max(0, taxableTotal - overallDisc);
    const cgstTotal = recalculatedItems.reduce((acc, it) => acc + it.cgstAmount, 0);
    const sgstTotal = recalculatedItems.reduce((acc, it) => acc + it.sgstAmount, 0);
    const igstTotal = recalculatedItems.reduce((acc, it) => acc + it.igstAmount, 0);
    const taxTotal = cgstTotal + sgstTotal + igstTotal;

    const addCharges = showAdditionalCharges ? Number(additionalChargesAmount) || 0 : 0;
    const unroundedGrand = finalTaxable + taxTotal + addCharges;

    let roundedGrand = unroundedGrand;
    let roundOff = 0;

    if (autoRoundOff) {
      roundedGrand = Math.round(unroundedGrand);
      roundOff = Number((roundedGrand - unroundedGrand).toFixed(2));
    } else {
      roundedGrand = Number((unroundedGrand + (Number(manualRoundOff) || 0)).toFixed(2));
      roundOff = Number(manualRoundOff) || 0;
    }

    return {
      totalQty,
      rawSubtotal: Number(rawSubtotal.toFixed(2)),
      itemDiscounts: Number(itemDiscounts.toFixed(2)),
      taxableTotal: Number(finalTaxable.toFixed(2)),
      cgstTotal: Number(cgstTotal.toFixed(2)),
      sgstTotal: Number(sgstTotal.toFixed(2)),
      igstTotal: Number(igstTotal.toFixed(2)),
      taxTotal: Number(taxTotal.toFixed(2)),
      additionalCharges: addCharges,
      roundOff,
      grandTotal: Math.max(0, roundedGrand),
    };
  }, [recalculatedItems, overallDiscountType, overallDiscountValue, showAdditionalCharges, additionalChargesAmount, autoRoundOff, manualRoundOff]);

  // Mark as fully paid sync
  useEffect(() => {
    if (markAsFullyPaid) {
      setAmountReceived(totals.grandTotal);
    }
  }, [markAsFullyPaid, totals.grandTotal]);

  // Sync billing when 'same as above' toggled or party address/state changes
  useEffect(() => {
    if (sameAsParty) {
      setBillingAddress(partyAddress || "");
      setBillingPincode("");
      setBillingPlaceOfSupply(placeOfSupply || "27-Maharashtra");
    }
  }, [sameAsParty, partyAddress, placeOfSupply]);

  const handleBillingAddressChange = (value: string) => {
    setBillingAddress(value);
    if (sameAsParty && value !== (partyAddress || "")) {
      setSameAsParty(false);
    }
  };

  const handleBillingPlaceChange = (value: string) => {
    setBillingPlaceOfSupply(value);
    if (sameAsParty && value !== (placeOfSupply || "27-Maharashtra")) {
      setSameAsParty(false);
    }
  };

  const handleUpdateItem = (index: number, field: keyof DocumentLineItem, value: DocumentLineItem[keyof DocumentLineItem]) => {
    setItems((prev) => {
      const copy = [...prev];
      copy[index] = { ...copy[index], [field]: value };
      return copy;
    });
  };

  const handleUpdateItemFields = (index: number, fields: Partial<DocumentLineItem>) => {
    setItems((prev) => {
      const copy = [...prev];
      copy[index] = { ...copy[index], ...fields };
      return copy;
    });
  };

  // Directly selecting product & auto-adding next line item like POS
  const handleSelectProduct = (index: number, product: UnifiedProductSuggestion) => {
    setItems((prev) => {
      const copy = [...prev];
      copy[index] = {
        ...copy[index],
        productId: product.id,
        productName: product.name,
        barcode: product.barcode || undefined,
        hsn: product.hsn || copy[index].hsn || "",
        unit: product.unit || copy[index].unit || "Pcs",
        altUnit: product.altUnit || undefined,
        altUnitConversion: product.altUnitConversion || undefined,
        altQty: undefined,
        rate: product.rate,
        batchNumber: product.batchNumber || undefined,
        taxRate: product.gstRate !== undefined ? product.gstRate : 18,
      };

      // Auto-add next item line if this was the last row
      if (index === copy.length - 1) {
        const nextId = `row-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`;
        copy.push(createNewRow(nextId));
      }
      return copy;
    });
    setActiveItemDropdown(null);
    focusItemInput(index + 1);
  };

  const handleOpenCreateItemDialog = (rowIndex: number, prefillName?: string) => {
    setActiveItemDropdown(null);
    setTargetRowIndexForNewItem(rowIndex);
    setInitialNewItemName(prefillName || "");
    setShowQuickCreateItemModal(true);
  };

  const handleItemCreated = (product: CreatedProductResult) => {
    const normalizedHsn = (product.hsn || "").trim();
    const catalogRow: ProductCatalogOption = {
      id: product.id,
      name: product.name,
      category: product.category || "General",
      barcode: product.barcode || null,
      sku: product.sku,
      unit: product.unit || "Pcs",
      altUnit: product.altUnit,
      altUnitConversion: product.altUnitConversion,
      tags: {
        hsn_code: normalizedHsn,
        gst_rate: product.taxRate,
        selling_price: product.sellingPrice,
        purchase_price: product.purchasePrice,
        mrp: product.sellingPrice || product.purchasePrice || 0,
        unit: product.unit || "Pcs",
        alt_unit: product.altUnit,
        alt_unit_conversion: product.altUnitConversion,
        min_stock_alert: 5,
      },
      product_batches: [
        {
          id: product.batchNumber || `batch-${product.id}`,
          batch_number: product.batchNumber || "BATCH-01",
          mrp: product.sellingPrice || product.purchasePrice || 0,
          stock: product.stock || 0,
          expiry_date: null,
        },
      ],
    };

    // Update shared product store so all views get refreshed
    try {
      addOrUpdateProduct(catalogRow);
    } catch (e) {
      console.warn('Failed to update shared product store', e);
    }

    if (targetRowIndexForNewItem !== null) {
      setItems((prev) => {
        const copy = [...prev];
        if (targetRowIndexForNewItem < copy.length) {
          copy[targetRowIndexForNewItem] = {
            ...copy[targetRowIndexForNewItem],
            productId: product.id,
            productName: product.name,
            barcode: product.barcode || undefined,
            hsn: normalizedHsn,
            unit: product.unit || copy[targetRowIndexForNewItem].unit || "Pcs",
            altUnit: product.altUnit || undefined,
            altUnitConversion: product.altUnitConversion || undefined,
            altQty: undefined,
            rate: product.sellingPrice,
            taxRate: product.taxRate,
            batchNumber: product.batchNumber || undefined,
          };
        }

        if (targetRowIndexForNewItem === copy.length - 1) {
          const nextId = `row-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`;
          copy.push(createNewRow(nextId));
        }
        return copy;
      });

      focusItemInput(targetRowIndexForNewItem + 1);
    }

    setTargetRowIndexForNewItem(null);
    setInitialNewItemName("");
    setShowQuickCreateItemModal(false);
  };

  // When user selects multiple items from the AddItemsToBillModal, insert them
  // at the row that opened the modal (addItemsTargetRow) if set; otherwise append.
  // The function preserves the existing behavior of ensuring a trailing empty row.
  const handleBatchAddItemsAtTarget = (newItems: DocumentLineItem[]) => {
    if (!newItems || newItems.length === 0) return;
    const target = addItemsTargetRow;

    setItems((prev) => {
      const copy = [...prev];

      // Normalize incoming items into the local DocumentLineItem shape
      const mapped = newItems.map((ni) => ({
        id: `row-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
        productId: (ni as any).productId || (ni as any).id || undefined,
        productName: (ni as any).productName || (ni as any).name || "",
        barcode: (ni as any).barcode || undefined,
        hsn: (ni as any).hsn || "",
        quantity: Number((ni as any).quantity) || 1,
        unit: (ni as any).unit || "Pcs",
        rate: Number((ni as any).rate) || 0,
        discountPercent: Number((ni as any).discountPercent) || 0,
        discountAmount: Number((ni as any).discountAmount) || 0,
        taxRate: Number((ni as any).taxRate) || 18,
        taxableAmount: Number((ni as any).taxableAmount) || 0,
        cgstAmount: Number((ni as any).cgstAmount) || 0,
        sgstAmount: Number((ni as any).sgstAmount) || 0,
        igstAmount: Number((ni as any).igstAmount) || 0,
        lineTotal: Number((ni as any).lineTotal) || 0,
      } as DocumentLineItem));

      // Determine insertion index
      let insertAt = copy.length; // default append
      if (typeof target === "number" && target >= 0 && target < copy.length) {
        insertAt = target;
      }

      // If target row exists and is empty (no productName), replace that row with first mapped item
      if (typeof target === "number" && target >= 0 && target < copy.length && (!copy[target].productName || copy[target].productName.trim() === "")) {
        // replace that single row with mapped items
        copy.splice(target, 1, ...mapped);
      } else {
        // splice in mapped items at insertAt
        copy.splice(insertAt, 0, ...mapped);
      }

      // Ensure trailing blank row exists
      const last = copy[copy.length - 1];
      if (!last || (last.productName && last.productName.trim() !== "")) {
        copy.push(createNewRow(`row-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`));
      }

      return copy;
    });

    // reset the remembered target and close modal
    setAddItemsTargetRow(null);
    setShowAddItemsModal(false);

    // Focus first new inserted row after a tick
    setTimeout(() => {
      const focusIndex = typeof target === "number" && target >= 0 ? target : (items.length - 1);
      focusItemInput(focusIndex + (newItems?.length ? newItems.length - 1 : 0));
    }, 80);
  };

  const handleSelectCustomer = (c: CustomerOption) => {
    setSelectedCustomerId(c.id);
    setPartyName(c.name);
    setCustomerSearch(c.name);
    setPartyPhone(c.phone || "");
    setPartyGstin(c.gstin || "");
    setPartyAddress(c.address || "");
    if (c.gstin && c.gstin.length >= 2) {
      const statePrefix = c.gstin.slice(0, 2);
      const match = INDIAN_STATES_AND_CODES.find((s) => s.startsWith(statePrefix));
      if (match) setPlaceOfSupply(match);
    }
    setShowCustomerDropdown(false);
  };

  const handleCreateCustomerInline = async () => {
    if (!newCustName.trim()) {
      toast.error("Please enter a customer name");
      return;
    }
    try {
      const { data, error } = await supabase
        .from("customers")
        .insert({
          organization_id: orgId,
          name: newCustName.trim(),
          phone: newCustPhone.trim() || undefined,
          email: undefined,
          address: newCustAddress.trim() || undefined,
        })
        .select()
        .single();

      if (error) throw error;

      toast.success(`Customer "${newCustName}" created successfully!`);
      const newOpt: CustomerOption = {
        id: data.id,
        name: data.name,
        phone: data.phone || "",
        address: data.address || "",
        balance: 0,
      };
      setCustomers((prev) => [newOpt, ...prev]);
      handleSelectCustomer(newOpt);
      setShowNewCustomerDialog(false);
      setNewCustName("");
      setNewCustPhone("");
      setNewCustGstin("");
      setNewCustAddress("");
    } catch (err: unknown) {
      toast.error(getErrorMessage(err, "Failed to create customer"));
    }
  };

  const handleSave = async (andPrint = false, saveAndNew = false) => {
    if (saving) return;
    if (!partyName.trim()) {
      toast.error("Please enter or select a customer name (Bill To)");
      return;
    }

    const validItems = recalculatedItems.filter((it) => it.productName.trim() !== "");
    if (validItems.length === 0) {
      toast.error("Please add at least one line item");
      return;
    }

    setSaving(true);
    try {
      const resolvedBillingAddress = sameAsParty ? (partyAddress.trim() || undefined) : (billingAddress.trim() || undefined);
      const resolvedBillingPlaceOfSupply = sameAsParty ? (placeOfSupply || "27-Maharashtra") : (billingPlaceOfSupply.trim() || placeOfSupply || "27-Maharashtra");

      const finalDoc: Omit<BusinessDocument, "id"> = {
        organizationId: orgId,
        docType,
        documentNumber: fullDocumentNumber,
        referenceNumber: ewayBillNo.trim() || undefined,
        partyId: selectedCustomerId || undefined,
        partyName: partyName.trim(),
        partyPhone: partyPhone.trim() || undefined,
        partyGstin: partyGstin.trim() || undefined,
        partyAddress: partyAddress.trim() || undefined,
        billingAddress: resolvedBillingAddress,
        billingPincode: sameAsParty ? undefined : (billingPincode.trim() || undefined),
        billingPlaceOfSupply: resolvedBillingPlaceOfSupply,
        placeOfSupply,
        docDate,
        dueDate: showDueDate ? dueDate : docDate,
        paymentTerms,
        items: validItems,
        subtotal: totals.rawSubtotal,
        discountTotal: totals.itemDiscounts + (overallDiscountValue || 0),
        taxableTotal: totals.taxableTotal,
        cgstTotal: totals.cgstTotal,
        sgstTotal: totals.sgstTotal,
        igstTotal: totals.igstTotal,
        taxTotal: totals.taxTotal,
        roundOff: totals.roundOff,
        grandTotal: totals.grandTotal,
        paidAmount: amountReceived,
        balanceDue: Math.max(0, totals.grandTotal - amountReceived),
        status:
          amountReceived >= totals.grandTotal
            ? "paid"
            : amountReceived > 0
            ? "partial"
            : "unpaid",
        paymentMethod,
        notes: showNotes ? notes : undefined,
        terms,
        transportDetails: vehicleNumber.trim() ? { vehicleNumber: vehicleNumber.trim() } : undefined,
        created_at: editingDoc?.created_at || new Date().toISOString(),
      };

      const saved = await documentsService.saveDocument(finalDoc, user?.id);

      // Auto-share with CredSmart network buyer for approval & auto-purchase sync
      if (docType === "sales_invoice") {
        try {
          const netInvoice = await networkInvoicingService.sendSalesInvoiceToNetwork(saved, org, user?.id);
          if (netInvoice) {
            toast.success(
              `ΓÜí Sales Invoice #${fullDocumentNumber} saved & shared with ${netInvoice.recipientOrgName} for purchase approval!`,
              { duration: 5000 }
            );
          } else {
            toast.success(`Sales Invoice ${fullDocumentNumber} saved successfully!`);
          }
        } catch (netErr) {
          console.warn("Network dispatch notice:", netErr);
          toast.success(`Sales Invoice ${fullDocumentNumber} saved successfully!`);
        }
      } else {
        toast.success(`Sales Invoice ${fullDocumentNumber} saved successfully!`);
      }
      onSaved(saved);

      if (andPrint && onPrintRequest) {
        onPrintRequest(saved);
      }

      if (saveAndNew) {
        const nextSeq = (parseInt(invoiceNumberSeq, 10) + 1 || Math.floor(100 + Math.random() * 900)).toString();
        setInvoiceNumberSeq(nextSeq);
        setPartyName("");
        setCustomerSearch("");
        setSelectedCustomerId("");
        setPartyPhone("");
        setPartyGstin("");
        setPartyAddress("");
        setBillingAddress("");
        setBillingPincode("");
        setBillingPlaceOfSupply("27-Maharashtra");
        setSameAsParty(false);
        setItems([createNewRow("row-1")]);
        setAmountReceived(0);
        setMarkAsFullyPaid(false);
      } else {
        onOpenChange(false);
      }
    } catch (err: unknown) {
      toast.error(getErrorMessage(err, "Failed to save invoice"));
    } finally {
      setSaving(false);
    }
  };

  // Print current invoice without saving (validation guards applied)
  const handlePrint = () => {
    if (!partyName.trim()) {
      toast.error("Please enter or select a customer name (Bill To)");
      return;
    }

    const validItems = recalculatedItems.filter((it) => it.productName.trim() !== "");
    if (validItems.length === 0) {
      toast.error("Please add at least one line item");
      return;
    }

    const resolvedBillingAddress = sameAsParty ? (partyAddress.trim() || undefined) : (billingAddress.trim() || undefined);
    const resolvedBillingPlaceOfSupply = sameAsParty ? (placeOfSupply || "27-Maharashtra") : (billingPlaceOfSupply.trim() || placeOfSupply || "27-Maharashtra");

    const docToPrint: BusinessDocument = {
      id: editingDoc?.id || `preview-${Date.now()}`,
      organizationId: orgId,
      docType,
      documentNumber: fullDocumentNumber,
      referenceNumber: ewayBillNo.trim() || undefined,
      partyId: selectedCustomerId || undefined,
      partyName: partyName.trim(),
      partyPhone: partyPhone.trim() || undefined,
      partyGstin: partyGstin.trim() || undefined,
      partyAddress: partyAddress.trim() || undefined,
      billingAddress: resolvedBillingAddress,
      billingPincode: sameAsParty ? undefined : (billingPincode.trim() || undefined),
      billingPlaceOfSupply: resolvedBillingPlaceOfSupply,
      placeOfSupply,
      docDate,
      dueDate: showDueDate ? dueDate : docDate,
      paymentTerms,
      items: validItems,
      subtotal: totals.rawSubtotal,
      discountTotal: totals.itemDiscounts + (overallDiscountValue || 0),
      taxableTotal: totals.taxableTotal,
      cgstTotal: totals.cgstTotal,
      sgstTotal: totals.sgstTotal,
      igstTotal: totals.igstTotal,
      taxTotal: totals.taxTotal,
      roundOff: totals.roundOff,
      grandTotal: totals.grandTotal,
      paidAmount: amountReceived,
      balanceDue: Math.max(0, totals.grandTotal - amountReceived),
      status: amountReceived >= totals.grandTotal ? "paid" : amountReceived > 0 ? "partial" : "unpaid",
      paymentMethod,
      notes: showNotes ? notes : undefined,
      terms,
      transportDetails: vehicleNumber.trim() ? { vehicleNumber: vehicleNumber.trim() } : undefined,
      created_at: new Date().toISOString(),
    };

    if (onPrintRequest) {
      onPrintRequest(docToPrint);
    } else {
      toast.error("No print handler available");
    }
  };

  const filteredCustomers = useMemo(() => {
    if (!customerSearch) return customers.slice(0, 20);
    const q = customerSearch.toLowerCase();
    return customers.filter((c) => {
      const safeName = (c?.name || "").toLowerCase();
      const safePhone = c?.phone || "";
      const safeGstin = c?.gstin || "";
      return safeName.includes(q) || safePhone.includes(q) || safeGstin.toLowerCase().includes(q);
    });
  }, [customers, customerSearch]);

  const getFilteredProducts = (query: string): UnifiedProductSuggestion[] => {
    const safeCatalog = (productsCatalog || []).filter(Boolean);

    const customPriceMap = new Map<string, number>();
    const customItemsList = activeCustomer?.customItems || [];

    if (activeCustomer && activeCustomer.keepSamePrice === false && customItemsList.length > 0) {
      customItemsList.forEach((ci) => {
        if (ci.productId) customPriceMap.set(ci.productId, ci.customPrice);
        if (ci.productName) customPriceMap.set(ci.productName.toLowerCase().trim(), ci.customPrice);
        if (ci.barcode) customPriceMap.set(ci.barcode.trim(), ci.customPrice);
      });
    }

    const synthesizedCustomSuggestions: UnifiedProductSuggestion[] = customItemsList.map((ci) => {
      const existing = safeCatalog.find(
        (p) =>
          p.id === ci.productId ||
          (ci.barcode && p.barcode === ci.barcode) ||
          (ci.productName && p.name?.toLowerCase().trim() === ci.productName.toLowerCase().trim())
      );

      if (existing) {
        const tags = (existing as any).tags || {};
        const defaultRate =
          tags && tags.selling_price !== undefined && tags.selling_price !== null
            ? Number(tags.selling_price)
            : existing.product_batches?.reduce((sum, b) => sum + (Number(b.mrp) || 0), 0) || 0;
        const rate =
          activeCustomer?.keepSamePrice === false && ci.customPrice !== undefined
            ? ci.customPrice
            : customPriceMap.get(existing.id) ?? defaultRate;

        return {
          id: existing.id,
          name: existing.name || ci.productName || "Unnamed Item",
          category: existing.category || ci.category || "General",
          barcode: existing.barcode || ci.barcode || undefined,
          sku: existing.sku || ci.sku,
          hsn: ci.hsnCode || tags?.hsn_code || tags?.hsn || (existing as any).hsn || undefined,
          unit: ci.unit || existing.unit || "Pcs",
          altUnit: (existing as any).altUnit || tags?.alt_unit || undefined,
          altUnitConversion: (existing as any).altUnitConversion ?? tags?.alt_unit_conversion ?? undefined,
          rate,
          gstRate: ci.gstRate || (tags && tags.gst_rate !== undefined ? Number(tags.gst_rate) : 18),
          stock: existing.product_batches?.reduce((sum, b) => sum + (Number(b.stock) || 0), 0) || ci.customStock || 0,
          isDb: true,
        };
      }

      return {
        id: ci.productId || `custom-${Date.now()}-${Math.random()}`,
        name: ci.productName || "Custom Product",
        category: ci.category || "General",
        barcode: ci.barcode || undefined,
        sku: ci.sku,
        hsn: ci.hsnCode,
        unit: ci.unit || "Pcs",
        rate: ci.customPrice || ci.standardPrice || 0,
        gstRate: ci.gstRate || 18,
        stock: ci.customStock || 999,
        isDb: true,
      };
    });

    if (activeCustomer && activeCustomer.keepSameInventory === false && customItemsList.length > 0) {
      if (!query) return synthesizedCustomSuggestions.slice(0, 15);
      const q = query.toLowerCase();
      return synthesizedCustomSuggestions.filter((p) => {
        const name = (p.name || "").toLowerCase();
        const barcode = (p.barcode || "").toLowerCase();
        const sku = (p.sku || "").toLowerCase();
        return name.includes(q) || barcode.includes(q) || sku.includes(q);
      }).slice(0, 15);
    }

    const toSuggestion = (p: ProductCatalogOption): UnifiedProductSuggestion => {
      const tags = (p as any).tags || {};
      const defaultRate = tags && (tags.selling_price !== undefined && tags.selling_price !== null)
        ? Number(tags.selling_price)
        : (p.product_batches?.reduce((sum, b) => sum + (Number(b.mrp) || 0), 0) || 0);
      const matchRate =
        customPriceMap.get(p.id) ??
        (p.name ? customPriceMap.get(p.name.toLowerCase().trim()) : undefined) ??
        (p.barcode ? customPriceMap.get(p.barcode.trim()) : undefined);
      const rate = matchRate !== undefined ? matchRate : defaultRate;
      const gst = tags && (tags.gst_rate !== undefined && tags.gst_rate !== null) ? Number(tags.gst_rate) : 18;
      const hsnVal = tags?.hsn_code || tags?.hsn || (p as any).hsn || undefined;
      const altUnitVal = (p as any).altUnit || tags?.alt_unit || undefined;
      const altConvVal = (p as any).altUnitConversion ?? tags?.alt_unit_conversion ?? undefined;

      return {
        id: p.id,
        name: p.name || "Unnamed Item",
        category: p.category || "General",
        barcode: p.barcode || undefined,
        sku: p.sku,
        hsn: hsnVal,
        unit: p.unit || "Pcs",
        altUnit: altUnitVal,
        altUnitConversion: altConvVal ? Number(altConvVal) : undefined,
        rate,
        gstRate: gst,
        stock: p.product_batches?.reduce((sum, b) => sum + (Number(b.stock) || 0), 0) || 0,
        isDb: true,
      };
    };

    const uniqueAdditional = synthesizedCustomSuggestions.filter(
      (cp) =>
        !safeCatalog.some(
          (p) =>
            p.id === cp.id ||
            (p.name && cp.name && p.name.toLowerCase().trim() === cp.name.toLowerCase().trim())
        )
    );

    const fullCatalogSuggestions = [...safeCatalog.map(toSuggestion), ...uniqueAdditional];

    if (!query) return fullCatalogSuggestions.slice(0, 15);

    const q = query.toLowerCase();
    return fullCatalogSuggestions
      .filter((p) => {
        const name = (p?.name || "").toLowerCase();
        const barcode = (p?.barcode || "").toLowerCase();
        const sku = (p?.sku || "").toLowerCase();
        return name.includes(q) || barcode.includes(q) || sku.includes(q);
      })
      .slice(0, 15);
  };

  const upiPayload = upiId
    ? `upi://pay?pa=${encodeURIComponent(upiId)}&pn=${encodeURIComponent(
        org?.name || "Business"
      )}&am=${totals.grandTotal}&cu=INR&tn=${encodeURIComponent(
        `Inv ${fullDocumentNumber}`
      )}`
    : "";

  return (
    <>
      <Dialog open={open} onOpenChange={onOpenChange}>
        <DialogContent className="bill-editor-shell z-modal w-full h-[100dvh] max-h-[100dvh] max-w-full rounded-none border-none p-0 sm:max-w-7xl sm:w-[98vw] sm:h-auto sm:max-h-[96vh] sm:rounded-none sm:border flex flex-col gap-0 overflow-visible bg-white dark:bg-slate-950">
          {/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
          {/* 1. TOP HEADER BAR */}
          {/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
          <div className="bill-editor-toolbar px-3 py-2.5 sm:px-4 sm:py-2.5 border-b border-slate-200 bg-white dark:bg-slate-900 flex flex-wrap items-center justify-between gap-3 shrink-0">
            <div className="flex items-center gap-3">
              <Button
                type="button"
                variant="outline"
                size="sm"
                onClick={() => onOpenChange(false)}
                className="h-8 px-2.5 text-xs font-semibold text-slate-700 dark:text-slate-200 border-slate-300 dark:border-slate-700 hover:bg-slate-100 dark:hover:bg-slate-800 gap-1.5 rounded-lg shadow-2xs cursor-pointer"
              >
                <ArrowLeft className="w-3.5 h-3.5" />
                Exit
              </Button>

              <h2 className="text-base sm:text-lg font-bold text-slate-900 dark:text-white tracking-tight flex items-center gap-2">
                <span>{editingDoc ? "Edit Sales Invoice" : "Create Sales Invoice"}</span>
              </h2>
            </div>


            {/* Right Actions */}
            <div className="flex items-center gap-2">
              <Button
                type="button"
                variant="ghost"
                size="icon"
                className="w-8 h-8 rounded-lg text-muted-foreground hover:text-foreground"
                title="Invoice Settings"
              >
                <Settings className="w-4 h-4" />
              </Button>

              <div className="flex items-center p-0.5 rounded-md bg-slate-100 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 mr-2">
                <button
                  type="button"
                  onClick={() => setViewMode("edit")}
                  className={cn(
                    "px-3 py-1.5 text-xs font-semibold rounded-lg flex items-center gap-1.5 transition-all cursor-pointer",
                    viewMode === "edit"
                      ? "bg-white dark:bg-slate-900 text-primary shadow-xs font-bold"
                      : "text-muted-foreground hover:text-foreground"
                  )}
                >
                  <Edit3 className="w-3.5 h-3.5" />
                  Edit
                </button>
                <button
                  type="button"
                  onClick={() => setViewMode("preview")}
                  className={cn(
                    "px-3 py-1.5 text-xs font-semibold rounded-lg flex items-center gap-1.5 transition-all cursor-pointer",
                    viewMode === "preview"
                      ? "bg-white dark:bg-slate-900 text-primary shadow-xs font-bold"
                      : "text-muted-foreground hover:text-foreground"
                  )}
                >
                  <Eye className="w-3.5 h-3.5" />
                  Preview
                </button>
              </div>

              <Button
                type="button"
                variant="outline"
                size="sm"
                onClick={() => handlePrint()}
                className="h-8 px-3 text-xs font-semibold border-slate-300 dark:border-slate-700 rounded-lg shadow-2xs cursor-pointer"
                title="Print"
              >
                <Printer className="w-3.5 h-3.5" />
              </Button>

              <Button
                type="button"
                variant="outline"
                size="sm"
                disabled={saving}
                onClick={() => handleSave(false, true)}
                className="h-8 px-3 text-xs font-semibold border-slate-300 dark:border-slate-700 rounded-lg shadow-2xs cursor-pointer"
              >
                Save &amp; New
              </Button>

            </div>
          </div>

          {/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
          {/* 2. BODY CONTENT */}
          {/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
          {viewMode === "preview" ? (
            <div className="flex-1 overflow-y-auto p-4 sm:p-8 bg-slate-200 dark:bg-slate-900 flex justify-center scrollbar-thin">
              <div className="w-full max-w-3xl bg-white dark:bg-card shadow-xl rounded-xl border border-border p-4 sm:p-6 overflow-hidden">
                <UnifiedInvoiceRenderer
                  docType="sales_invoice"
                  invoiceNumber={fullDocumentNumber}
                  invoiceDate={docDate}
                  dueDate={showDueDate ? dueDate : undefined}
                  storeInfo={{
                    name: org?.name || "CredSmart Store",
                    phone: org?.phone || "",
                    email: org?.email || "",
                    address: org?.address || "",
                    gstin: org?.gstin || "",
                    pan: org?.pan || "",
                    logoUrl: org?.logo_url || "",
                    bank_name: bankAccount.bankName || org?.bank_name,
                    account_number: bankAccount.accountNumber || org?.account_number,
                    ifsc: bankAccount.ifsc || org?.ifsc,
                    account_holder: bankAccount.accountHolder || org?.account_holder || org?.name,
                    upi_id: upiId || org?.upi_id,
                  }}
                  party={{
                    name: partyName || "Customer",
                    phone: partyPhone,
                    address: partyAddress,
                    gstin: partyGstin,
                    state: placeOfSupply,
                  }}
                  items={recalculatedItems.map((it) => ({
                    id: it.id,
                    name: it.productName || "Item",
                    hsn: it.hsn,
                    qty: Number(it.quantity) || 1,
                    unit: it.unit || "Pcs",
                    altUnit: it.altUnit,
                    altQty: it.altQty,
                    altUnitConversion: it.altUnitConversion,
                    rate: Number(it.rate) || 0,
                    discount: it.discountPercent || 0,
                    discountPercent: it.discountPercent,
                    taxRate: it.taxRate || 18,
                    taxAmount: (it.taxRate || 18) * (it.taxableAmount || 0) / 100,
                    total: it.lineTotal,
                  }))}
                  totals={{
                    subtotal: totals.rawSubtotal,
                    discountTotal: totals.itemDiscounts + (overallDiscountValue || 0),
                    taxableAmount: totals.taxableTotal,
                    taxTotal: totals.taxTotal,
                    cgst: totals.cgstTotal,
                    sgst: totals.sgstTotal,
                    igst: totals.igstTotal,
                    grandTotal: totals.grandTotal,
                  }}
                  notes={showNotes ? notes : undefined}
                  terms={terms}
                  propBankDetails={showBankDetails && bankAccount.accountNumber ? bankAccount : undefined}
                  propUpiId={showPaymentQr && upiId ? upiId : undefined}
                />
              </div>
            </div>
          ) : (
            <div ref={editorBodyRef} className="bill-editor-body flex-1 min-h-0 overflow-y-auto p-1 sm:p-1 space-y-1 scrollbar-thin">
              {/* TOP ROW: Bill To (Dropdown Format) & Invoice Details */}
              <div className="grid grid-cols-1 lg:grid-cols-12 gap-4">
                {/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
                {/* BILL TO CARD (Dropdown Format with Balance) */}
                {/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
                <div className="bill-panel lg:col-span-6 bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 p-4 sm:p-5 shadow-2xs space-y-3">
                  <div className="flex items-center justify-between pb-2 border-b border-slate-100 dark:border-slate-800">
                    <span className="text-xs font-bold text-slate-700 dark:text-slate-300 uppercase tracking-wider flex items-center gap-1.5">
                      <Building2 className="w-3.5 h-3.5 text-primary" />
                      Bill To
                    </span>
                    <button
                      type="button"
                      onClick={() => setShowNewCustomerDialog(true)}
                      className="text-muted-foreground hover:text-primary transition-colors"
                      title="Add Customer"
                    >
                      <UserPlus className="w-3.5 h-3.5" />
                    </button>
                  </div>

                  {/* Search / Dropdown Input */}
                  {!partyName.trim() && !showCustomerDropdown && (
                    <button
                      type="button"
                      onClick={() => setShowCustomerDropdown(true)}
                      className="w-full h-[104px] border border-dashed border-primary/40 hover:border-primary/70 bg-white dark:bg-slate-900 text-primary text-xs font-semibold flex items-center justify-center transition-colors cursor-pointer"
                    >
                      + Add Party
                    </button>
                  )}
                  <div className={cn("relative", !partyName.trim() && !showCustomerDropdown && "hidden")}>
                    <div
                      className="flex items-center justify-between border border-slate-300 dark:border-slate-700 rounded-lg px-3 py-2 bg-white dark:bg-slate-900 cursor-pointer shadow-2xs hover:border-primary/60 transition-colors"
                      onClick={() => setShowCustomerDropdown(true)}
                    >
                      <input
                        placeholder="Search party by name or number"
                        value={showCustomerDropdown ? customerSearch : (partyName || customerSearch)}
                        onChange={(e) => {
                          setCustomerSearch(e.target.value);
                          setShowCustomerDropdown(true);
                        }}
                        onFocus={() => setShowCustomerDropdown(true)}
                        className="w-full text-xs font-semibold text-slate-900 dark:text-white bg-transparent focus:outline-none placeholder:text-slate-400 placeholder:font-normal"
                      />
                      <ChevronDown className="w-4 h-4 text-slate-400 shrink-0" />
                    </div>

                    {showCustomerDropdown && (
                      <div className="absolute z-[200] left-0 right-0 top-full mt-1 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-2xl overflow-hidden divide-y divide-slate-100 dark:divide-slate-800">
                        {/* Table Header Strip */}
                        <div className="px-3.5 py-2 bg-slate-100/90 dark:bg-slate-800/80 flex items-center justify-between text-[11px] font-bold text-slate-600 dark:text-slate-300 uppercase tracking-wider">
                          <span>Party Name</span>
                          <span>Balance</span>
                        </div>

                        {/* List of Parties */}
                        <div className="max-h-56 overflow-y-auto divide-y divide-slate-100 dark:divide-slate-800">
                          {filteredCustomers.map((c) => (
                            <button
                              key={c.id}
                              type="button"
                              onMouseDown={(e) => {
                                e.preventDefault();
                                handleSelectCustomer(c);
                              }}
                              className="w-full text-left px-3.5 py-2.5 hover:bg-primary/5 dark:hover:bg-primary/10 transition-colors flex items-center justify-between gap-3 group cursor-pointer"
                            >
                              <div className="flex-1 min-w-0 pr-2">
                                <p className="font-bold text-xs text-slate-900 dark:text-white uppercase tracking-tight truncate">
                                  {c.name}
                                </p>
                                {c.phone && (
                                  <p className="text-[10px] text-slate-500 font-mono mt-0.5">{c.phone}</p>
                                )}
                              </div>
                              <div className="text-right shrink-0">
                                <span className={cn(
                                  "font-mono font-bold text-xs flex items-center justify-end gap-1",
                                  (c.balance || 0) > 0 ? "text-slate-800 dark:text-slate-200" : "text-slate-500"
                                )}>
                                  Γé╣ {(c.balance || 0).toLocaleString("en-IN")}
                                  {(c.balance || 0) > 0 && <span className="text-[10px] text-emerald-600">Γåô</span>}
                                </span>
                              </div>
                            </button>
                          ))}
                          {filteredCustomers.length === 0 && (
                            <div className="p-4 text-center text-xs text-muted-foreground">
                              No party found matching "{customerSearch}"
                            </div>
                          )}
                        </div>

                        {/* Bottom Action: + Create Party */}
                        <div className="p-2 bg-slate-50 dark:bg-slate-800/40">
                          <button
                            type="button"
                            onMouseDown={(e) => {
                              e.preventDefault();
                              setShowNewCustomerDialog(true);
                              setShowCustomerDropdown(false);
                            }}
                            className="w-full py-2 rounded-lg border border-dashed border-primary/40 hover:border-primary text-primary text-xs font-bold flex items-center justify-center gap-1.5 hover:bg-primary/5 transition-all cursor-pointer"
                          >
                            <Plus className="w-3.5 h-3.5" />
                            + Create Party
                          </button>
                        </div>
                      </div>
                    )}
                  </div>

                  {/* Selected Party Summary Card */}
                  {partyName.trim() && !showCustomerDropdown && (
                    <div className="p-3 rounded-lg bg-slate-50/80 dark:bg-slate-800/40 border border-slate-200 dark:border-slate-700/60 space-y-1.5">
                      <div className="flex items-start justify-between gap-2">
                        <div>
                          <h4 className="text-xs font-bold text-slate-900 dark:text-white flex items-center gap-1.5">
                            {partyName}
                            {partyGstin && (
                              <span className="text-[9px] font-mono font-medium px-1 py-0.2 rounded bg-indigo-50 dark:bg-indigo-950 text-indigo-700 dark:text-indigo-300 border border-indigo-200 dark:border-indigo-800">
                                GST: {partyGstin}
                              </span>
                            )}
                          </h4>
                          {partyPhone && (
                            <p className="text-[11px] text-slate-600 dark:text-slate-400 font-mono">
                              Phone: {partyPhone}
                            </p>
                          )}
                          {partyAddress && (
                            <p className="text-[11px] text-slate-500 dark:text-slate-400 truncate max-w-xs">
                              {partyAddress}
                            </p>
                          )}
                          <p className="text-[10px] text-slate-500 mt-0.5">
                            Place of Supply: <span className="font-semibold text-slate-700 dark:text-slate-300">{placeOfSupply}</span>
                          </p>
                        </div>

                        <Button
                          type="button"
                          variant="ghost"
                          size="sm"
                          onClick={() => {
                            setShowCustomerDropdown(true);
                            setCustomerSearch("");
                          }}
                          className="h-6 px-2 text-[11px] text-primary hover:text-primary font-semibold shrink-0"
                        >
                          Change
                        </Button>
                      </div>

                      {connectedPartner && (
                        <div className="mt-2 pt-2 border-t border-emerald-500/20 flex items-start gap-2 bg-emerald-500/10 p-2 rounded-md">
                          <Sparkles className="w-4 h-4 text-emerald-600 dark:text-emerald-400 shrink-0 mt-0.5" />
                          <div className="text-[11px] flex-1">
                            <span className="font-bold text-emerald-800 dark:text-emerald-300">
                              ΓÜí Connected CredSmart Store: {connectedPartner.name}
                            </span>
                            <p className="text-[10px] text-emerald-700 dark:text-emerald-400 mt-0.5">
                              Saving this invoice will automatically send an in-app notification to {connectedPartner.name} to approve &amp; inward this into their Purchases.
                            </p>
                          </div>
                        </div>
                      )}
                    </div>
                  )}

                  <div className="mt-3 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50/70 dark:bg-slate-800/40 p-3 space-y-2.5">
                    <div className="flex items-center justify-between gap-3">
                      <Label className="text-[11px] font-semibold text-slate-600 dark:text-slate-300 uppercase tracking-wide">
                        Billing Address
                      </Label>
                      <div className="flex items-center gap-2">
                        <Checkbox
                          id="same-as-party-address"
                          checked={sameAsParty}
                          onCheckedChange={(checked) => {
                            const isChecked = Boolean(checked);
                            setSameAsParty(isChecked);
                            if (isChecked) {
                              setBillingAddress(partyAddress || "");
                              setBillingPincode("");
                              setBillingPlaceOfSupply(placeOfSupply || "27-Maharashtra");
                            }
                          }}
                        />
                        <Label htmlFor="same-as-party-address" className="text-[10px] text-slate-600 dark:text-slate-400 cursor-pointer">
                          Same as Party Address
                        </Label>
                      </div>
                    </div>

                    <Textarea
                      value={billingAddress}
                      onChange={(e) => handleBillingAddressChange(e.target.value)}
                      disabled={sameAsParty}
                      placeholder="Enter billing address"
                      className="min-h-[78px] text-xs bg-white dark:bg-slate-900 border-slate-300 dark:border-slate-700 disabled:opacity-100 disabled:cursor-default"
                    />

                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                      <div>
                        <Label className="text-[10px] font-semibold text-slate-600 dark:text-slate-400">
                          Pincode
                        </Label>
                        <Input
                          value={billingPincode}
                          onChange={(e) => {
                            setBillingPincode(e.target.value);
                            if (sameAsParty) setSameAsParty(false);
                          }}
                          placeholder="400001"
                          className="h-8 text-xs mt-1 bg-white dark:bg-slate-900 border-slate-300 dark:border-slate-700"
                        />
                      </div>

                      <div>
                        <Label className="text-[10px] font-semibold text-slate-600 dark:text-slate-400">
                          State
                        </Label>
                        <Select value={billingPlaceOfSupply} onValueChange={handleBillingPlaceChange}>
                          <SelectTrigger className="h-8 text-xs mt-1 bg-white dark:bg-slate-900 border-slate-300 dark:border-slate-700">
                            <SelectValue />
                          </SelectTrigger>
                          <SelectContent>
                            {INDIAN_STATES_AND_CODES.map((state) => (
                              <SelectItem key={state} value={state}>
                                {state}
                              </SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                      </div>
                    </div>
                  </div>
                </div>

                {/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
                {/* INVOICE DETAILS CARD */}
                {/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
                <div className="bill-panel lg:col-span-6 bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 p-4 sm:p-5 shadow-2xs space-y-3.5">
                  <div className="flex items-center justify-between pb-2.5 border-b border-slate-100 dark:border-slate-800">
                    <span className="text-xs font-bold text-slate-700 dark:text-slate-300 uppercase tracking-wider">
                      Invoice Details
                    </span>
                    <div className="flex items-center gap-3">
                      <div className="flex items-center gap-1.5">
                        <Switch
                          checked={repeatInvoice}
                          onCheckedChange={setRepeatInvoice}
                          id="repeat-inv"
                          className="scale-75"
                        />
                        <Label htmlFor="repeat-inv" className="text-[11px] text-slate-600 dark:text-slate-400 cursor-pointer">
                          Repeat this invoice
                        </Label>
                      </div>
                      <Settings className="w-3.5 h-3.5 text-muted-foreground" />
                    </div>
                  </div>

                  {/* Row 1: Invoice Prefix & Invoice Number */}
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                    <div>
                      <Label className="text-[11px] font-semibold text-slate-600 dark:text-slate-400">
                        Invoice Prefix
                      </Label>
                      <Input
                        value={invoicePrefix}
                        onChange={(e) => setInvoicePrefix(e.target.value)}
                        placeholder="KE/26-27/"
                        className="h-8 text-xs font-mono font-medium mt-1 bg-slate-50/50 dark:bg-slate-800/50"
                      />
                    </div>
                    <div>
                      <Label className="text-[11px] font-semibold text-slate-600 dark:text-slate-400">
                        Invoice Number
                      </Label>
                      <Input
                        value={invoiceNumberSeq}
                        onChange={(e) => setInvoiceNumberSeq(e.target.value)}
                        placeholder="130"
                        className="h-8 text-xs font-mono font-bold mt-1 bg-slate-50/50 dark:bg-slate-800/50"
                      />
                    </div>
                  </div>

                  {/* Row 2: Sales Invoice Date */}
                  <div>
                    <Label className="text-[11px] font-semibold text-slate-600 dark:text-slate-400">
                      Sales Invoice Date
                    </Label>
                    <div className="relative mt-1">
                      <Input
                        type="date"
                        value={docDate}
                        onChange={(e) => setDocDate(e.target.value)}
                        className="h-8 text-xs font-medium pl-8 bg-slate-50/50 dark:bg-slate-800/50"
                      />
                      <CalendarIcon className="w-3.5 h-3.5 text-slate-400 absolute left-2.5 top-2.5 pointer-events-none" />
                    </div>
                  </div>

                  {/* Row 3: Due Date Toggle */}
                  {showDueDate ? (
                    <div className="grid grid-cols-2 gap-3 pt-1">
                      <div>
                        <Label className="text-[11px] font-semibold text-slate-600 dark:text-slate-400">
                          Payment Terms
                        </Label>
                        <Select value={paymentTerms} onValueChange={setPaymentTerms}>
                          <SelectTrigger className="h-8 text-xs mt-1 bg-slate-50/50 dark:bg-slate-800/50">
                            <SelectValue />
                          </SelectTrigger>
                          <SelectContent>
                            {PAYMENT_TERMS_SUGGESTIONS.map((t) => (
                              <SelectItem key={t.value} value={t.value}>
                                {t.label}
                              </SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                      </div>
                      <div>
                        <div className="flex items-center justify-between">
                          <Label className="text-[11px] font-semibold text-slate-600 dark:text-slate-400">
                            Due Date
                          </Label>
                          <button
                            type="button"
                            onClick={() => setShowDueDate(false)}
                            className="text-[10px] text-rose-500 hover:underline cursor-pointer"
                          >
                            Remove
                          </button>
                        </div>
                        <Input
                          type="date"
                          value={dueDate}
                          onChange={(e) => setDueDate(e.target.value)}
                          className="h-8 text-xs font-medium mt-1 bg-slate-50/50 dark:bg-slate-800/50"
                        />
                      </div>
                    </div>
                  ) : (
                    <button
                      type="button"
                      onClick={() => setShowDueDate(true)}
                      className="w-full py-1.5 border border-dashed border-primary/30 hover:border-primary/60 rounded-lg text-primary text-xs font-semibold flex items-center justify-center gap-1.5 transition-colors cursor-pointer"
                    >
                      <Plus className="w-3.5 h-3.5" />
                      + Add Due Date
                    </button>
                  )}

                  {/* Row 4: E-Way Bill No & Vehicle No */}
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 pt-1">
                    <div>
                      <Label className="text-[11px] font-semibold text-slate-600 dark:text-slate-400 flex items-center gap-1">
                        E-Way Bill No. <HelpCircle className="w-3 h-3 text-slate-400" />
                      </Label>
                      <Input
                        value={ewayBillNo}
                        onChange={(e) => setEwayBillNo(e.target.value)}
                        placeholder="e.g. 241098765432"
                        className="h-8 text-xs font-mono mt-1 bg-slate-50/50 dark:bg-slate-800/50"
                      />
                    </div>
                    <div>
                      <Label className="text-[11px] font-semibold text-slate-600 dark:text-slate-400">
                        Vehicle No.
                      </Label>
                      <Input
                        value={vehicleNumber}
                        onChange={(e) => setVehicleNumber(e.target.value.toUpperCase())}
                        placeholder="e.g. MH-12-AB-1234"
                        className="h-8 text-xs font-mono uppercase mt-1 bg-slate-50/50 dark:bg-slate-800/50"
                      />
                    </div>
                  </div>
                </div>
              </div>

              {/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
              {/* 3. LINE ITEMS TABLE (Direct POS-Style + Auto Add Next Line) */}
              {/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
              {activeCustomer && (activeCustomer.keepSamePrice === false || activeCustomer.keepSameInventory === false) && (
                <div className="p-2.5 rounded-xl bg-primary/10 border border-primary/20 flex items-center justify-between gap-2 text-xs mb-2">
                  <div className="flex items-center gap-2 text-primary font-medium">
                    <Sparkles className="w-4 h-4 text-primary shrink-0" />
                    <span>
                      <strong>Custom Party Catalog Active:</strong> {activeCustomer.name}
                      {activeCustomer.keepSamePrice === false && " ΓÇó Custom Prices Applied"}
                      {activeCustomer.keepSameInventory === false && ` ΓÇó Restricted to ${activeCustomer.customItems?.length || 0} product(s)`}
                    </span>
                  </div>
                  <Badge variant="outline" className="text-[10px] bg-background font-semibold">
                    Party Rule Active
                  </Badge>
                </div>
              )}
              <div className="bill-panel bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 overflow-hidden shadow-2xs">
                <div className="overflow-x-auto">
                  <table className="w-full min-w-[760px] text-left text-xs border-collapse">
                    <thead>
                      <tr className="bg-slate-50 dark:bg-slate-800/70 border-b border-slate-200 dark:border-slate-800 text-[11px] font-bold text-slate-600 dark:text-slate-300 uppercase tracking-wider">
                        <th className="py-2.5 px-3 w-10 text-center">NO</th>
                        <th className="py-2.5 px-3 min-w-[260px]">ITEMS</th>
                        <th className="py-2.5 px-2 w-20">HSN</th>
                        <th className="py-2.5 px-2 w-16 text-center">QTY</th>
                        <th className="py-2.5 px-2 w-24 text-center">UNIT</th>
                        <th className="py-2.5 px-2 w-28 text-right">PRICE/ITEM (Γé╣)</th>
                        <th className="py-2.5 px-2 w-20 text-center">DISCOUNT</th>
                        <th className="py-2.5 px-2 w-20 text-center">TAX</th>
                        <th className="py-2.5 px-3 w-28 text-right">AMOUNT (Γé╣)</th>
                        <th className="py-2.5 px-2 w-10 text-center">
                          <Settings className="w-3.5 h-3.5 text-muted-foreground mx-auto" />
                        </th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
                      {recalculatedItems.map((item, idx) => (
                        <tr key={item.id} className="hover:bg-slate-50/50 dark:hover:bg-slate-800/30 transition-colors">
                          <td className="py-2 px-3 text-center text-slate-400 font-mono text-xs">
                            {idx + 1}
                          </td>

                          {/* Product selection replaced by an explicit Add Items button (opens modal)
                              per user's request: typing field replaced with a simple button that shows
                              the full inventory. This preserves Create New Item flow via the modal too. */}
                                  <td className="py-2 px-3 relative">
                                    <div className="flex items-center gap-2">
                                      <button
                                        type="button"
                                        onClick={async () => {
                                          // Remember which row opened the Add Items modal ΓÇö useful if
                                          // the batch-add handler wants to insert at that row.
                                          setAddItemsTargetRow(idx);
                                          // If catalog is empty for some reason (stale state), try fetching again
                                          try {
                                            if ((productsCatalog || []).length === 0) {
                                              // fetchProducts is defined in this component scope
                                              await fetchProducts();
                                            }
                                          } catch (e) {
                                            console.warn('Failed to refresh product catalog before opening Add Items modal', e);
                                          }
                                          setShowAddItemsModal(true);
                                        }}
                                        className="w-full text-left px-3 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 text-xs font-semibold hover:bg-slate-50 dark:hover:bg-slate-800 transition-colors flex items-center justify-between gap-2"
                                      >
                                        <div className="flex items-center gap-2">
                                          <Package className="w-4 h-4 text-primary" />
                                          <div className="text-left">
                                            <div className="truncate text-sm font-medium text-slate-900 dark:text-white">{item.productName || "Add Item To Bill"}</div>
                                            <div className="text-[10px] text-muted-foreground">{item.hsn ? `HSN: ${item.hsn}` : "Select from inventory"}</div>
                                          </div>
                                        </div>
                                        <div className="text-xs text-muted-foreground">Open</div>
                                      </button>
                                    </div>
                                  </td>

                          {/* HSN */}
                          <td className="py-2 px-2">
                            <Input
                              value={item.hsn || ""}
                              onChange={(e) => handleUpdateItem(idx, "hsn", e.target.value)}
                              placeholder="HSN"
                              className="h-8 text-xs font-mono bg-transparent"
                            />
                          </td>

                          {/* Qty (Pressing Enter auto advances) */}
                          <td className="py-2 px-2">
                            <Input
                              type="number"
                              min="1"
                              value={item.altUnit && item.altUnitConversion && item.altQty != null ? item.altQty : item.quantity}
                              onChange={(e) => {
                                const val = Math.max(1, Number(e.target.value));
                                if (item.altUnit && item.altUnitConversion && item.altQty != null) {
                                  handleUpdateItemFields(idx, {
                                    altQty: val,
                                    quantity: val * item.altUnitConversion,
                                  });
                                } else {
                                  handleUpdateItem(idx, "quantity", val);
                                }
                              }}
                              onKeyDown={(e) => {
                                if (e.key === "Enter") {
                                  e.preventDefault();
                                  if (idx === recalculatedItems.length - 1) {
                                    handleAddRow();
                                  } else {
                                    focusItemInput(idx + 1);
                                  }
                                }
                              }}
                              className="h-8 text-xs text-center font-mono font-semibold bg-transparent"
                            />
                            {item.altUnit && item.altUnitConversion && item.altQty != null && (
                              <span className="block text-[9px] text-blue-600 dark:text-blue-400 font-mono font-semibold text-center mt-0.5 whitespace-nowrap">
                                ({item.altQty}*{item.altUnitConversion} {item.unit || "Pcs"})
                              </span>
                            )}
                          </td>

                          {/* Unit */}
                          <td className="py-2 px-2">
                            {item.altUnit && item.altUnitConversion && item.altUnitConversion > 1 ? (
                              <div className="flex flex-col items-center gap-0.5">
                                <div className="inline-flex rounded-md border border-primary/40 overflow-hidden text-[10px] font-bold bg-white dark:bg-slate-900 shadow-2xs">
                                  <button
                                    type="button"
                                    onClick={() => handleUpdateItemFields(idx, { altQty: undefined })}
                                    className={cn(
                                      "px-2 py-1 transition-colors cursor-pointer",
                                      item.altQty == null
                                        ? "bg-primary text-primary-foreground font-bold"
                                        : "text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800"
                                    )}
                                  >
                                    {item.unit || "PCS"}
                                  </button>
                                  <button
                                    type="button"
                                    onClick={() => {
                                      const altQ = Math.max(1, Math.round((item.quantity || 1) / item.altUnitConversion!));
                                      handleUpdateItemFields(idx, {
                                        altQty: altQ,
                                        quantity: altQ * item.altUnitConversion!,
                                      });
                                    }}
                                    className={cn(
                                      "px-2 py-1 transition-colors border-l border-primary/40 cursor-pointer",
                                      item.altQty != null
                                        ? "bg-primary text-primary-foreground font-bold"
                                        : "text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800"
                                    )}
                                  >
                                    {item.altUnit}
                                  </button>
                                </div>
                                <span className="text-[8.5px] text-muted-foreground font-mono whitespace-nowrap">
                                  1 {item.altUnit} = {item.altUnitConversion} {item.unit || "Pcs"}
                                </span>
                              </div>
                            ) : (
                              <Select
                                value={item.unit || "Pcs"}
                                onValueChange={(val) => handleUpdateItem(idx, "unit", val)}
                              >
                                <SelectTrigger className="h-8 text-xs bg-transparent font-medium">
                                  <SelectValue />
                                </SelectTrigger>
                                <SelectContent className="max-h-56">
                                  {["PCS", "KG", "LTR", "BOX", "NOS", "MTR", "PKT", "DOZ", "BAG", "CAN", "BTL", "SET", "GM", "ML", "STEPS"].map((u) => (
                                    <SelectItem key={u} value={u} className="text-xs">
                                      {u}
                                    </SelectItem>
                                  ))}
                                </SelectContent>
                              </Select>
                            )}
                          </td>

                          {/* Price / Rate */}
                          <td className="py-2 px-2">
                            <Input
                              type="number"
                              min="0"
                              step="0.01"
                              value={item.rate}
                              onChange={(e) => handleUpdateItem(idx, "rate", Number(e.target.value))}
                              onKeyDown={(e) => {
                                if (e.key === "Enter") {
                                  e.preventDefault();
                                  if (idx === recalculatedItems.length - 1) {
                                    handleAddRow();
                                  } else {
                                    focusItemInput(idx + 1);
                                  }
                                }
                              }}
                              className="h-8 text-xs text-right font-mono font-semibold bg-transparent"
                            />
                          </td>

                          {/* Discount */}
                          <td className="py-2 px-2">
                            <Input
                              type="number"
                              min="0"
                              max="100"
                              value={item.discountPercent || ""}
                              onChange={(e) => handleUpdateItem(idx, "discountPercent", Number(e.target.value))}
                              placeholder="%"
                              className="h-8 text-xs text-center font-mono bg-transparent"
                            />
                          </td>

                          {/* Tax Dropdown */}
                          <td className="py-2 px-2">
                            <Select
                              value={String(item.taxRate)}
                              onValueChange={(val) => handleUpdateItem(idx, "taxRate", Number(val))}
                            >
                              <SelectTrigger className="h-8 text-xs bg-transparent">
                                <SelectValue />
                              </SelectTrigger>
                              <SelectContent>
                                <SelectItem value="0">0%</SelectItem>
                                <SelectItem value="5">5%</SelectItem>
                                <SelectItem value="12">12%</SelectItem>
                                <SelectItem value="18">18%</SelectItem>
                                <SelectItem value="28">28%</SelectItem>
                              </SelectContent>
                            </Select>
                          </td>

                          {/* Amount */}
                          <td className="py-2 px-3 text-right font-mono font-bold text-slate-900 dark:text-white">
                            Γé╣{item.lineTotal.toFixed(2)}
                          </td>

                          {/* Remove button */}
                          <td className="py-2 px-2 text-center">
                            <button
                              type="button"
                              onClick={() => handleRemoveRow(idx)}
                              className="text-slate-400 hover:text-rose-500 transition-colors p-1 rounded cursor-pointer"
                            >
                              <Trash2 className="w-3.5 h-3.5" />
                            </button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>

                {/* Direct Add Item Row Actions (Like POS) */}
                <div className="p-3 bg-slate-50/70 dark:bg-slate-850 border-t border-slate-200 dark:border-slate-800 flex flex-wrap items-center justify-between gap-2.5">
                  <div className="flex items-center gap-2 flex-1 min-w-[200px] flex-wrap">
                      {/* Buttons removed as per user request: Add Item To Bill, Create New Item, Add Blank Row */}
                    </div>

                    <div className="flex items-center gap-2">
                      {/* Scan Barcode removed as per user request */}
                    </div>
                </div>

                {/* Subtotals Summary Strip */}
                <div className="px-4 py-2.5 bg-slate-100/90 dark:bg-slate-800 border-t border-slate-200 dark:border-slate-800 flex items-center justify-between text-xs font-semibold text-slate-700 dark:text-slate-300">
                  <span>Subtotal</span>
                  <div className="flex items-center gap-6 font-mono">
                    <span>Qty: <strong className="text-slate-900 dark:text-white">{totals.totalQty}</strong></span>
                    <span>Tax: <strong className="text-slate-900 dark:text-white">Γé╣{totals.taxTotal.toFixed(2)}</strong></span>
                    <span>Total: <strong className="text-slate-900 dark:text-white">Γé╣{totals.rawSubtotal.toFixed(2)}</strong></span>
                  </div>
                </div>
              </div>

              {/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
              {/* 4. BOTTOM SECTION: Split 2 Columns */}
              {/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
              <div className="grid grid-cols-1 lg:grid-cols-12 gap-5 items-start">
                {/* LEFT COLUMN: Notes, Terms, Bank Details, Payment QR */}
                <div className="lg:col-span-6 space-y-4">
                  {showNotes ? (
                    <div className="bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 p-3.5 space-y-1.5 shadow-2xs">
                      <div className="flex items-center justify-between">
                        <Label className="text-xs font-bold text-slate-700 dark:text-slate-300 flex items-center gap-1.5">
                          <FileText className="w-3.5 h-3.5 text-primary" />
                          Notes &amp; Remarks
                        </Label>
                        <button
                          type="button"
                          onClick={() => {
                            setShowNotes(false);
                            setNotes("");
                          }}
                          className="text-[11px] text-rose-500 hover:underline cursor-pointer"
                        >
                          Remove
                        </button>
                      </div>
                      <Textarea
                        value={notes}
                        onChange={(e) => setNotes(e.target.value)}
                        placeholder="Add remarks or notes for the customer..."
                        rows={2}
                        className="text-xs resize-none"
                      />
                    </div>
                  ) : (
                    <button
                      type="button"
                      onClick={() => setShowNotes(true)}
                      className="text-xs text-primary font-semibold flex items-center gap-1.5 hover:underline py-1 cursor-pointer"
                    >
                      <FileText className="w-3.5 h-3.5" />
                      Add Notes
                    </button>
                  )}

                  {/* Terms & Conditions */}
                  <div className="bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 overflow-hidden shadow-2xs">
                    <button
                      type="button"
                      onClick={() => setTermsOpen((prev) => !prev)}
                      className="w-full p-3.5 flex items-center justify-between text-left hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors cursor-pointer"
                    >
                      <span className="text-xs font-bold text-slate-800 dark:text-slate-200">
                        Terms &amp; Conditions
                      </span>
                      {termsOpen ? <ChevronUp className="w-4 h-4 text-slate-400" /> : <ChevronDown className="w-4 h-4 text-slate-400" />}
                    </button>
                    {termsOpen && (
                      <div className="px-3.5 pb-3.5 pt-0">
                        <Textarea
                          value={terms}
                          onChange={(e) => setTerms(e.target.value)}
                          rows={2}
                          className="text-xs text-slate-600 dark:text-slate-300 font-sans resize-none leading-relaxed bg-slate-50/50 dark:bg-slate-800/30"
                        />
                      </div>
                    )}
                  </div>

                  {/* Bank Details Card */}
                  {showBankDetails && (
                    <div className="bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 p-4 shadow-2xs space-y-2.5">
                      <span className="text-xs font-bold text-slate-800 dark:text-slate-200 block">
                        Bank Details
                      </span>

                      {bankAccount.accountNumber ? (
                        <div className="grid grid-cols-2 gap-y-2 gap-x-4 text-xs">
                          <div>
                            <span className="text-slate-500 text-[11px]">Account Number:</span>
                            <p className="font-mono font-bold text-slate-900 dark:text-white">
                              {bankAccount.accountNumber}
                            </p>
                          </div>
                          <div>
                            <span className="text-slate-500 text-[11px]">IFSC Code:</span>
                            <p className="font-mono font-bold text-slate-900 dark:text-white">
                              {bankAccount.ifsc}
                            </p>
                          </div>
                          <div>
                            <span className="text-slate-500 text-[11px]">Bank &amp; Branch Name:</span>
                            <p className="font-semibold text-slate-800 dark:text-slate-200">
                              {bankAccount.bankName} {bankAccount.branch ? `, ${bankAccount.branch}` : ""}
                            </p>
                          </div>
                          <div>
                            <span className="text-slate-500 text-[11px]">Account Holder's Name:</span>
                            <p className="font-semibold text-slate-800 dark:text-slate-200">
                              {bankAccount.accountHolder || org?.name || "Store Owner"}
                            </p>
                          </div>
                        </div>
                      ) : (
                        <p className="text-xs text-muted-foreground italic">
                          No default bank configured in settings.
                        </p>
                      )}

                      <div className="flex items-center gap-3 pt-2 border-t border-slate-100 dark:border-slate-800 text-xs">
                        <button
                          type="button"
                          onClick={() => setShowBankDetails(false)}
                          className="text-rose-500 hover:underline flex items-center gap-1 font-medium cursor-pointer"
                        >
                          <Trash2 className="w-3 h-3" /> Remove
                        </button>
                        <button
                          type="button"
                          onClick={() => {
                            const newAcc = prompt("Enter Bank Account Number:", bankAccount.accountNumber);
                            if (newAcc !== null) setBankAccount((p) => ({ ...p, accountNumber: newAcc }));
                          }}
                          className="text-primary hover:underline flex items-center gap-1 font-medium cursor-pointer"
                        >
                          <RotateCcw className="w-3 h-3" /> Change
                        </button>
                      </div>
                    </div>
                  )}

                  {/* Payment QR Card */}
                  {showPaymentQr && (
                    <div className="bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 p-4 shadow-2xs flex items-center justify-between gap-4">
                      <div className="flex items-center gap-3.5">
                        <div className="p-1 bg-white border border-slate-200 rounded-lg shadow-2xs shrink-0">
                          {upiPayload ? (
                            <QRCodeSVG value={upiPayload} size={54} level="M" />
                          ) : (
                            <QrCode className="w-12 h-12 text-slate-400 p-1" />
                          )}
                        </div>
                        <div>
                          <span className="text-xs font-bold text-slate-800 dark:text-slate-200 flex items-center gap-1">
                            Payment QR <HelpCircle className="w-3 h-3 text-slate-400" />
                          </span>
                          <p className="text-xs text-slate-600 dark:text-slate-400 font-mono mt-0.5">
                            {upiId || "No UPI ID set"}
                          </p>
                        </div>
                      </div>

                      <div className="flex flex-col items-end gap-1.5 text-xs">
                        <button
                          type="button"
                          onClick={() => setShowPaymentQr(false)}
                          className="text-rose-500 hover:underline flex items-center gap-1 font-medium cursor-pointer"
                        >
                          <Trash2 className="w-3 h-3" /> Remove
                        </button>
                        <button
                          type="button"
                          onClick={() => {
                            const newUpi = prompt("Enter UPI ID (e.g. store@upi):", upiId);
                            if (newUpi !== null) setUpiId(newUpi);
                          }}
                          className="text-primary hover:underline flex items-center gap-1 font-medium cursor-pointer"
                        >
                          <RotateCcw className="w-3 h-3" /> Change
                        </button>
                      </div>
                    </div>
                  )}
                </div>

                {/* RIGHT COLUMN: Calculations, Totals, Settlement & Stamp */}
                <div className="bill-panel lg:col-span-6 bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 p-4 sm:p-5 shadow-2xs space-y-3.5">
                  {showAdditionalCharges ? (
                    <div className="p-3 rounded-lg bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 space-y-2">
                      <div className="flex items-center justify-between">
                        <Label className="text-xs font-semibold text-slate-700 dark:text-slate-300">
                          Additional Charges
                        </Label>
                        <button
                          type="button"
                          onClick={() => {
                            setShowAdditionalCharges(false);
                            setAdditionalChargesAmount(0);
                          }}
                          className="text-[10px] text-rose-500 hover:underline cursor-pointer"
                        >
                          Remove
                        </button>
                      </div>
                      <div className="grid grid-cols-2 gap-2">
                        <Input
                          value={additionalChargesReason}
                          onChange={(e) => setAdditionalChargesReason(e.target.value)}
                          placeholder="e.g. Shipping / Packing"
                          className="h-7 text-xs"
                        />
                        <Input
                          type="number"
                          min="0"
                          value={additionalChargesAmount || ""}
                          onChange={(e) => setAdditionalChargesAmount(Number(e.target.value))}
                          placeholder="Amount (Γé╣)"
                          className="h-7 text-xs font-mono font-semibold"
                        />
                      </div>
                    </div>
                  ) : (
                    <button
                      type="button"
                      onClick={() => setShowAdditionalCharges(true)}
                      className="text-xs text-primary font-semibold flex items-center gap-1 hover:underline cursor-pointer"
                    >
                      <Plus className="w-3.5 h-3.5" /> Add Additional Charges
                    </button>
                  )}

                  {/* Taxable Amount */}
                  <div className="flex items-center justify-between text-xs text-slate-600 dark:text-slate-400 py-1">
                    <span>Taxable Amount</span>
                    <span className="font-mono font-bold text-slate-900 dark:text-white">
                      Γé╣{totals.taxableTotal.toFixed(2)}
                    </span>
                  </div>

                  {/* Add Discount link */}
                  {showDiscount ? (
                    <div className="p-3 rounded-lg bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 space-y-2">
                      <div className="flex items-center justify-between">
                        <Label className="text-xs font-semibold text-slate-700 dark:text-slate-300">
                          Overall Discount
                        </Label>
                        <button
                          type="button"
                          onClick={() => {
                            setShowDiscount(false);
                            setOverallDiscountValue(0);
                          }}
                          className="text-[10px] text-rose-500 hover:underline cursor-pointer"
                        >
                          Remove
                        </button>
                      </div>
                      <div className="grid grid-cols-2 gap-2">
                        <Select
                          value={overallDiscountType}
                          onValueChange={(val) => setOverallDiscountType(val as "flat" | "percent")}
                        >
                          <SelectTrigger className="h-7 text-xs">
                            <SelectValue />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectItem value="flat">Flat Amount (Γé╣)</SelectItem>
                            <SelectItem value="percent">Percentage (%)</SelectItem>
                          </SelectContent>
                        </Select>
                        <Input
                          type="number"
                          min="0"
                          value={overallDiscountValue || ""}
                          onChange={(e) => setOverallDiscountValue(Number(e.target.value))}
                          placeholder="Discount value"
                          className="h-7 text-xs font-mono font-semibold"
                        />
                      </div>
                    </div>
                  ) : (
                    <button
                      type="button"
                      onClick={() => setShowDiscount(true)}
                      className="text-xs text-primary font-semibold flex items-center gap-1 hover:underline cursor-pointer"
                    >
                      <Plus className="w-3.5 h-3.5" /> Add Discount
                    </button>
                  )}

                  {/* Auto Round Off */}
                  <div className="flex items-center justify-between text-xs py-1 border-t border-slate-100 dark:border-slate-800">
                    <div className="flex items-center gap-2">
                      <Checkbox
                        id="round-off"
                        checked={autoRoundOff}
                        onCheckedChange={(checked) => setAutoRoundOff(!!checked)}
                      />
                      <Label htmlFor="round-off" className="text-xs font-medium text-slate-700 dark:text-slate-300 cursor-pointer">
                        Auto Round Off
                      </Label>
                    </div>
                    {!autoRoundOff && (
                      <div className="flex items-center gap-1 font-mono text-xs">
                        <Input
                          type="number"
                          step="0.01"
                          value={manualRoundOff}
                          onChange={(e) => setManualRoundOff(Number(e.target.value))}
                          className="h-7 w-20 text-right font-mono"
                        />
                      </div>
                    )}
                  </div>

                  {/* Total Amount (Prominent Bold Display) */}
                  <div className="p-3.5 rounded-xl bg-slate-50 dark:bg-slate-850 border border-slate-200 dark:border-slate-700/80 flex items-center justify-between">
                    <span className="text-sm font-black text-slate-900 dark:text-white uppercase tracking-wider">
                      Total Amount:
                    </span>
                    <span className="text-xl font-black font-mono text-primary">
                      Γé╣ {totals.grandTotal.toLocaleString("en-IN", { minimumFractionDigits: 2 })}
                    </span>
                  </div>

                  {/* Total Amount Received & Mode */}
                  <div className="space-y-1.5 pt-1">
                    <div className="flex items-center justify-between text-xs">
                      <span className="font-semibold text-slate-700 dark:text-slate-300">Total Amount Received</span>
                      <span className="font-mono font-bold text-slate-900 dark:text-white">
                        Γé╣ {amountReceived.toFixed(2)}
                      </span>
                    </div>

                    <div className="flex items-center gap-2">
                      <div className="relative flex-1">
                        <span className="absolute left-2.5 top-2 text-xs text-slate-400 font-mono">Γé╣</span>
                        <Input
                          type="number"
                          min="0"
                          value={amountReceived || ""}
                          onChange={(e) => {
                            setAmountReceived(Number(e.target.value));
                            if (Number(e.target.value) >= totals.grandTotal) {
                              setMarkAsFullyPaid(true);
                            } else {
                              setMarkAsFullyPaid(false);
                            }
                          }}
                          placeholder="0"
                          className="h-8 text-xs font-mono font-bold pl-6"
                        />
                      </div>

                      <Select value={paymentMethod} onValueChange={setPaymentMethod}>
                        <SelectTrigger className="h-8 text-xs w-28 shrink-0">
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="Cash">Cash</SelectItem>
                          <SelectItem value="UPI">UPI</SelectItem>
                          <SelectItem value="Card">Card</SelectItem>
                          <SelectItem value="Net Banking">Net Banking</SelectItem>
                          <SelectItem value="Cheque">Cheque</SelectItem>
                          <SelectItem value="Credit">Credit</SelectItem>
                        </SelectContent>
                      </Select>
                    </div>

                    {/* Mark as fully paid checkbox */}
                    <div className="flex items-center gap-2 pt-1">
                      <Checkbox
                        id="fully-paid"
                        checked={markAsFullyPaid}
                        onCheckedChange={(checked) => setMarkAsFullyPaid(!!checked)}
                      />
                      <Label htmlFor="fully-paid" className="text-xs text-slate-600 dark:text-slate-400 cursor-pointer">
                        Mark as fully paid
                      </Label>
                    </div>
                  </div>

                  {/* Balance Amount */}
                  <div className="flex items-center justify-between text-xs py-2 border-t border-slate-100 dark:border-slate-800 font-semibold">
                    <span className="text-slate-600 dark:text-slate-400">Balance Amount</span>
                    <span className={cn("font-mono font-bold text-sm", totals.grandTotal - amountReceived > 0 ? "text-rose-600 dark:text-rose-400" : "text-emerald-600 dark:text-emerald-400")}>
                      Γé╣ {Math.max(0, totals.grandTotal - amountReceived).toFixed(2)}
                    </span>
                  </div>

                  {/* Stamp / Signature Box */}
                  {showStamp && (
                    <div className="pt-2 border-t border-slate-100 dark:border-slate-800 flex flex-col items-end">
                      <div className="w-36 h-16 rounded-lg border border-dashed border-slate-300 dark:border-slate-700 bg-slate-50 dark:bg-slate-800/40 flex items-center justify-center p-1 overflow-hidden">
                        {stampUrl ? (
                          <img src={stampUrl} alt="Store Stamp" className="max-h-full max-w-full object-contain" />
                        ) : (
                          <div className="text-center">
                            <span className="text-[10px] text-muted-foreground font-serif italic">Authorized Signatory</span>
                          </div>
                        )}
                      </div>
                      <div className="flex items-center gap-2 text-[11px] mt-1.5">
                        <button
                          type="button"
                          onClick={() => setShowStamp(false)}
                          className="text-rose-500 hover:underline flex items-center gap-0.5 cursor-pointer"
                        >
                          <Trash2 className="w-3 h-3" /> Remove
                        </button>
                        <button
                          type="button"
                          onClick={() => {
                            const newUrl = prompt("Enter Signature / Stamp Image URL:", stampUrl);
                            if (newUrl !== null) setStampUrl(newUrl);
                          }}
                          className="text-primary hover:underline flex items-center gap-0.5 cursor-pointer"
                        >
                          <RotateCcw className="w-3 h-3" /> Change
                        </button>
                      </div>
                    </div>
                  )}
                </div>
              </div>
            </div>
          )}
        </DialogContent>
      </Dialog>

      {/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      {/* INLINE QUICK ADD CUSTOMER MODAL */}
      {/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      <Dialog open={showNewCustomerDialog} onOpenChange={setShowNewCustomerDialog}>
        <DialogContent className="z-modal max-w-md rounded-2xl p-5">
          <DialogHeader>
            <DialogTitle className="text-base font-bold flex items-center gap-2">
              <UserPlus className="w-4 h-4 text-primary" />
              Add New Party (Customer)
            </DialogTitle>
            <DialogDescription className="text-xs">
              Quickly save party details into your CRM directory
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-3 py-2 text-xs">
            <div>
              <Label className="text-xs font-semibold">Customer / Trade Name *</Label>
              <Input
                value={newCustName}
                onChange={(e) => setNewCustName(e.target.value)}
                placeholder="e.g. Ramesh Enterprises"
                className="mt-1 text-xs"
              />
            </div>
            <div>
              <Label className="text-xs font-semibold">Phone Number</Label>
              <Input
                value={newCustPhone}
                onChange={(e) => setNewCustPhone(e.target.value)}
                placeholder="10-digit mobile"
                className="mt-1 text-xs font-mono"
              />
            </div>
            <div>
              <Label className="text-xs font-semibold">GSTIN (Optional)</Label>
              <Input
                value={newCustGstin}
                onChange={(e) => setNewCustGstin(e.target.value.toUpperCase())}
                placeholder="27ABCDE1234F1Z5"
                className="mt-1 text-xs font-mono uppercase"
              />
            </div>
            <div>
              <Label className="text-xs font-semibold">Billing Address</Label>
              <Input
                value={newCustAddress}
                onChange={(e) => setNewCustAddress(e.target.value)}
                placeholder="Shop 14, Main Market, City"
                className="mt-1 text-xs"
              />
            </div>
          </div>

          <div className="flex items-center justify-end gap-2 pt-3 border-t">
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={() => setShowNewCustomerDialog(false)}
              className="text-xs"
            >
              Cancel
            </Button>
            <Button
              type="button"
              size="sm"
              onClick={handleCreateCustomerInline}
              className="text-xs font-bold bg-primary text-primary-foreground"
            >
              Save Customer
            </Button>
          </div>
        </DialogContent>
      </Dialog>

      {/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      {/* ADD ITEMS TO BILL MODAL */}
      {/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      <AddItemsToBillModal
        open={showAddItemsModal}
        onOpenChange={setShowAddItemsModal}
        items={billItemOptions}
        onAddSelectedItems={handleBatchAddItemsAtTarget}
        priceMode="sales"
        onOpenCreateItem={() => {
          setShowAddItemsModal(false);
          handleOpenCreateItemDialog(recalculatedItems.length - 1, "");
        }}
      />

      {/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      {/* DIRECT INLINE QUICK CREATE ITEM & ADD TO INVENTORY MODAL */}
      {/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      <QuickCreateItemModal
        open={showQuickCreateItemModal}
        onOpenChange={setShowQuickCreateItemModal}
        orgId={orgId}
        initialName={initialNewItemName}
        priceMode="sales"
        onItemCreated={handleItemCreated}
      />
    </>
  );
}

import { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Settings, Save, CheckCircle2, Sliders, Receipt, Percent } from "lucide-react";
import { toast } from "sonner";

interface SalesSettingsModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  orgId: string;
}

export interface SalesSettingsData {
  invoicePrefix: string;
  quotationPrefix: string;
  challanPrefix: string;
  creditNotePrefix: string;
  defaultPaymentTerms: string;
  defaultTaxRate: number;
  autoRoundOff: boolean;
  showSignature: boolean;
  defaultNotes: string;
  defaultTerms: string;
  printSize: "80mm" | "58mm" | "a4";
}

const DEFAULT_SETTINGS: SalesSettingsData = {
  invoicePrefix: "INV-",
  quotationPrefix: "EST-",
  challanPrefix: "DC-",
  creditNotePrefix: "CN-",
  defaultPaymentTerms: "Due on Receipt",
  defaultTaxRate: 18,
  autoRoundOff: true,
  showSignature: true,
  defaultNotes: "Thank you for your business!",
  defaultTerms: "1. Goods once sold will not be taken back without original bill.\n2. Interest @ 18% p.a. will be charged on overdue payments.",
  printSize: "80mm",
};

export function SalesSettingsModal({ open, onOpenChange, orgId }: SalesSettingsModalProps) {
  const [settings, setSettings] = useState<SalesSettingsData>(DEFAULT_SETTINGS);

  useEffect(() => {
    if (!orgId) return;
    try {
      const saved = localStorage.getItem(`credsmart_sales_settings_${orgId}`);
      if (saved) {
        setSettings({ ...DEFAULT_SETTINGS, ...JSON.parse(saved) });
      }
    } catch {}
  }, [orgId, open]);

  const handleSave = () => {
    try {
      localStorage.setItem(`credsmart_sales_settings_${orgId}`, JSON.stringify(settings));
      toast.success("Sales settings updated successfully");
      onOpenChange(false);
    } catch (e) {
      toast.error("Failed to save settings");
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-3xl sm:max-w-4xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 rounded-lg bg-indigo-50 dark:bg-indigo-950 flex items-center justify-center text-indigo-600">
              <Settings className="w-5 h-5" />
            </div>
            <div>
              <DialogTitle className="text-lg font-bold">Sales &amp; Invoicing Preferences</DialogTitle>
              <DialogDescription className="text-xs">
                Configure document prefixes, default GST tax rates, payment terms, and printing defaults.
              </DialogDescription>
            </div>
          </div>
        </DialogHeader>

        <div className="space-y-5 py-3 text-sm">
          {/* Document Prefixes */}
          <div className="p-4 rounded-xl bg-slate-50 dark:bg-slate-900/60 border border-border/80 space-y-3">
            <h3 className="font-semibold text-xs text-foreground uppercase tracking-wider flex items-center gap-1.5">
              <Receipt className="w-4 h-4 text-indigo-500" />
              Document Numbering Prefixes
            </h3>
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
              <div>
                <Label className="text-xs">Sales Invoice</Label>
                <Input
                  value={settings.invoicePrefix}
                  onChange={(e) => setSettings({ ...settings, invoicePrefix: e.target.value })}
                  placeholder="INV-"
                  className="mt-1 font-mono text-xs"
                />
              </div>
              <div>
                <Label className="text-xs">Quotation / Est.</Label>
                <Input
                  value={settings.quotationPrefix}
                  onChange={(e) => setSettings({ ...settings, quotationPrefix: e.target.value })}
                  placeholder="EST-"
                  className="mt-1 font-mono text-xs"
                />
              </div>
              <div>
                <Label className="text-xs">Delivery Challan</Label>
                <Input
                  value={settings.challanPrefix}
                  onChange={(e) => setSettings({ ...settings, challanPrefix: e.target.value })}
                  placeholder="DC-"
                  className="mt-1 font-mono text-xs"
                />
              </div>
              <div>
                <Label className="text-xs">Credit Note</Label>
                <Input
                  value={settings.creditNotePrefix}
                  onChange={(e) => setSettings({ ...settings, creditNotePrefix: e.target.value })}
                  placeholder="CN-"
                  className="mt-1 font-mono text-xs"
                />
              </div>
            </div>
