export type UniversalDocType =
  | "sales_invoice"
  | "purchase_invoice"
  | "pos_invoice"
  | "quotation"
  | "delivery_challan"
  | "credit_note"
  | "debit_note"
  | "proforma_invoice"
  | "payment_in"
  | "payment_out";

export interface InvoiceItemData {
  id?: string;
  name: string;
  description?: string;
  hsn?: string;
  qty: number;            // base/primary qty (always in primary unit like PCS)
  unit?: string;          // primary unit label
  altUnit?: string;       // alternate unit label (e.g. "PKT")
  altQty?: number;        // qty in alternate units (e.g. 2 PKT). qty = altQty ├ù altUnitConversion
  altUnitConversion?: number; // how many primary units per 1 alt unit
  freeQty?: number;
  rate: number;
  mrp?: number;
  discount?: number;
  discountPercent?: number;
  taxRate?: number;
  taxAmount?: number;
  total: number;
  batchNo?: string;
  expDate?: string;
  mfgDate?: string;
  priceHistory?: string;
}

export interface UnifiedInvoiceProps {
  docType?: UniversalDocType;
  invoiceNumber: string;
  referenceNumber?: string;
  date: string | Date;
  dueDate?: string;
  time?: string;
  storeInfo?: {
    name?: string;
    phone?: string;
    email?: string;
    address?: string;
    gstin?: string;
    pan?: string;
    logoUrl?: string;
    bank_name?: string;
    account_number?: string;
    ifsc?: string;
    account_holder?: string;
    upi_id?: string;
  };
  partyInfo?: {
    name?: string | null;
    phone?: string | null;
    email?: string | null;
    address?: string | null;
    gstin?: string | null;
    balance?: number | null;
    type?: "customer" | "supplier";
  };
  items: InvoiceItemData[];
  totals: {
    subtotal: number;
    discountTotal?: number;
    discountLabel?: string;
    taxableAmount?: number;
    cgst?: number;
    sgst?: number;
    igst?: number;
    taxTotal?: number;
    roundOff?: number;
    grandTotal: number;
    paidAmount?: number;
    balanceDue?: number;
  };
