                              </SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                      </div>
                      <div className="space-y-1.5">
                        <Label htmlFor="alt-unit-conversion" className="text-xs font-semibold">
                          {unit}s per {altUnit || "Alt Unit"}
                        </Label>
                        <Input
                          id="alt-unit-conversion"
                          type="number"
                          min="1"
                          step="1"
                          placeholder="e.g. 4"
