                      required
                      min="0"
                      step="0.01"
                    />
                  </div>
                </div>

                <div className="space-y-1.5">
                  <Label htmlFor="item-mrp" className="text-xs font-semibold">
                    MRP (Maximum Retail Price Γé╣)
                  </Label>
                  <div className="relative">
                    <span className="absolute left-3 top-1/2 -translate-y-1/2 text-sm font-bold text-muted-foreground">
                      Γé╣
                    </span>
                    <Input
                      id="item-mrp"
                      type="number"
                      placeholder="0.00"
                      className="pl-8 text-sm font-bold"
                      value={mrp}
                      onChange={(e) => setMrp(e.target.value)}
                      min="0"
                      step="0.01"
                    />
                  </div>
                </div>
              </div>

              {/* Profit Margin Indicator */}
              {sellingPrice && purchasePrice && parseFloat(sellingPrice) > 0 && (
                <div className="p-3 rounded-xl bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-between text-xs">
                  <span className="text-emerald-700 dark:text-emerald-300 font-semibold">
                    Gross Profit Margin:
                  </span>
                  <span className="font-mono font-black text-emerald-600 dark:text-emerald-400">
                    Γé╣ {(parseFloat(sellingPrice) - parseFloat(purchasePrice)).toFixed(2)} (
                    {(((parseFloat(sellingPrice) - parseFloat(purchasePrice)) / parseFloat(purchasePrice || "1")) * 100).toFixed(1)}
                    %)
                  </span>
                </div>
              )}

              {/* GST Rate & HSN Code Lookup */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <Label className="text-xs font-semibold">GST Tax Rate (%)</Label>
                  <Select value={gstRate.toString()} onValueChange={(v) => setGstRate(parseFloat(v) as GSTRate)}>
                    <SelectTrigger>
                      <SelectValue placeholder="Select GST Rate" />
                    </SelectTrigger>
                    <SelectContent>
                      {GST_RATES.map((rate) => (
                        <SelectItem key={rate} value={rate.toString()}>
                          {rate}% GST {rate === 0 ? "(Exempted)" : rate === 5 ? "(Essential Food)" : rate === 18 ? "(Standard)" : rate === 28 ? "(Luxury / Aerated)" : ""}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>

                <div className="space-y-1.5 relative">
                  <div className="flex items-center justify-between">
                    <Label htmlFor="hsn-code" className="text-xs font-semibold">
                      HSN / SAC Code
                    </Label>
                    <span className="text-[10px] text-muted-foreground">Type to search HSN library</span>
                  </div>
                  <div className="relative">
                    <Input
                      id="hsn-code"
                      placeholder="e.g. 0402 (Dairy), 1905 (Biscuits)"
                      value={hsnCode}
                      onChange={(e) => handleHsnSearchChange(e.target.value)}
                      onFocus={() => {
                        if (hsnCode) handleHsnSearchChange(hsnCode);
                      }}
                      className="font-mono"
                    />
                    <Search className="w-4 h-4 text-muted-foreground absolute right-3 top-1/2 -translate-y-1/2" />
                  </div>

                  {showHsnDropdown && hsnSuggestions.length > 0 && (
                    <div className="absolute z-[200] top-full left-0 right-0 mt-1 bg-card border border-border rounded-xl shadow-xl max-h-48 overflow-y-auto divide-y divide-border text-xs">
                      {hsnSuggestions.map((h) => (
                        <button
                          key={h.code}
                          type="button"
                          onClick={() => handleSelectHsn(h)}
                          className="w-full text-left p-2.5 hover:bg-muted/50 transition-colors flex items-center justify-between group"
                        >
                          <div>
                            <span className="font-bold text-foreground font-mono mr-2">{h.code}</span>
                            <span className="text-muted-foreground text-[11px]">{h.description}</span>
                          </div>
                          <Badge variant="outline" className="text-[10px] shrink-0 font-mono">
                            {h.gstRate}% GST
                          </Badge>
                        </button>
                      ))}
                    </div>
                  )}
                </div>
              </div>
            </div>
          )}

          {/* TAB 3: Inventory & Godown */}
          {activeTab === "stock" && (
            <div className="space-y-5">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <Label htmlFor="opening-stock" className="text-xs font-semibold">
                    Opening Stock Quantity ({unit})
                  </Label>
                  <Input
                    id="opening-stock"
                    type="number"
                    placeholder="0"
                    value={openingStock}
                    onChange={(e) => setOpeningStock(e.target.value)}
                    min="0"
                  />
                  <p className="text-[11px] text-muted-foreground">Initial inventory on-hand balance</p>
                </div>

                <div className="space-y-1.5">
                  <Label htmlFor="min-stock" className="text-xs font-semibold">
                    Low Stock Alert Level ({unit})
                  </Label>
                  <Input
                    id="min-stock"
                    type="number"
                    placeholder="10"
                    value={minStockAlert}
                    onChange={(e) => setMinStockAlert(e.target.value)}
                    min="0"
                  />
                  <p className="text-[11px] text-muted-foreground">
                    Triggers reorder warning when stock reaches this threshold
                  </p>
                </div>
              </div>

              <div className="space-y-1.5">
                <Label className="text-xs font-semibold">Default Godown / Warehouse Location</Label>
                <Select value={godownId} onValueChange={setGodownId}>
                  <SelectTrigger>
                    <SelectValue placeholder="Select Warehouse" />
                  </SelectTrigger>
                  <SelectContent>
                    {godowns.map((g) => (
                      <SelectItem key={g.id} value={g.id}>
                        {g.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                <p className="text-[11px] text-muted-foreground">
                  Stock will be assigned to this facility upon item creation
                </p>
              </div>
            </div>
          )}

          {/* TAB 4: Batch & Expiry Tracking */}
          {activeTab === "batch" && (
            <div className="space-y-5">
              <div className="flex items-center justify-between p-4 rounded-xl border border-border bg-muted/20">
                <div className="space-y-0.5">
                  <p className="font-bold text-foreground text-xs">Enable Batch & Expiry Tracking</p>
                  <p className="text-[11px] text-muted-foreground">
                    Crucial for Pharma, Dairy, FMCG & Perishables with FEFO inventory rotation
                  </p>
                </div>
                <Switch checked={trackBatches} onCheckedChange={setTrackBatches} />
              </div>

              {trackBatches && (
                <div className="space-y-4 p-4 rounded-xl border border-border bg-card animate-in fade-in duration-200">
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <div className="space-y-1.5">
                      <Label htmlFor="batch-number" className="text-xs font-semibold">
                        Batch Number
                      </Label>
                      <Input
                        id="batch-number"
                        placeholder="e.g. BATCH-2026A"
                        value={batchNumber}
                        onChange={(e) => setBatchNumber(e.target.value.toUpperCase())}
                        className="font-mono text-xs uppercase"
                      />
                    </div>

                    <div className="space-y-1.5">
                      <Label htmlFor="mfg-date" className="text-xs font-semibold">
                        Manufacturing Date
                      </Label>
                      <Input
                        id="mfg-date"
                        type="date"
                        value={manufacturingDate}
                        onChange={(e) => setManufacturingDate(e.target.value)}
                      />
                    </div>

                    <div className="space-y-1.5">
                      <Label htmlFor="expiry-date" className="text-xs font-semibold">
                        Expiry Date
                      </Label>
                      <Input
                        id="expiry-date"
                        type="date"
                        value={expiryDate}
                        onChange={(e) => setExpiryDate(e.target.value)}
                      />
                    </div>
                  </div>
                </div>
              )}
            </div>
          )}

          {/* Footer Navigation */}
          <div className="flex items-center justify-between pt-4 border-t border-border">
            <div>
              {activeTab !== "basic" && (
                <Button
                  type="button"
                  variant="ghost"
                  size="sm"
                  onClick={() => {
                    if (activeTab === "pricing") setActiveTab("basic");
                    else if (activeTab === "stock") setActiveTab("pricing");
                    else if (activeTab === "batch") setActiveTab("stock");
                  }}
                >
                  ΓåÉ Back
                </Button>
              )}
            </div>

            <div className="flex items-center gap-2 sm:gap-3 flex-wrap justify-end">
              <Button type="button" variant="outline" size="sm" onClick={onClose} disabled={isSubmitting}>
                Cancel
              </Button>
              {activeTab !== "batch" && (
                <Button
                  type="button"
                  size="sm"
                  variant="outline"
                  onClick={() => {
                    if (activeTab === "basic") setActiveTab("pricing");
                    else if (activeTab === "pricing") setActiveTab("stock");
                    else if (activeTab === "stock") setActiveTab("batch");
                  }}
                  className="gap-1.5"
                >
                  Continue ΓåÆ
                </Button>
              )}
              <Button type="submit" size="sm" disabled={isSubmitting} className="gap-2 font-bold bg-primary text-primary-foreground shadow-md">
                {isSubmitting ? (
                  <div className="w-4 h-4 border-2 border-primary-foreground border-t-transparent rounded-full animate-spin" />
                ) : (
                  <CheckCircle2 className="w-4 h-4" />
                )}
                {initialData ? "Update Item" : "Save Item"}
              </Button>
            </div>
          </div>
        </form>
      </div>
    </div>
  );
}

import { useState } from "react";
import {
  X,
  Sparkles,
  Percent,
  Gift,
  Tag,
  Calendar,
  CheckCircle2,
  Zap,
} from "lucide-react";
import { ItemOffer } from "@/types/inventory";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { toast } from "sonner";
import { cn } from "@/lib/utils";

interface CreateOfferModalProps {
  isOpen: boolean;
  onClose: () => void;
  categories: string[];
  onSaveOffer?: (offer: ItemOffer) => void;
}

export function CreateOfferModal({
  isOpen,
  onClose,
  categories,
  onSaveOffer,
}: CreateOfferModalProps) {
  const [title, setTitle] = useState("");
  const [offerType, setOfferType] = useState<"percentage" | "flat" | "bogo" | "bundle">("percentage");
  const [discountValue, setDiscountValue] = useState("10");
  const [selectedCategory, setSelectedCategory] = useState("all");
  const [minOrderValue, setMinOrderValue] = useState("500");
  const [couponCode, setCouponCode] = useState("FESTIVE10");
  const [startDate, setStartDate] = useState(new Date().toISOString().slice(0, 10));
  const [endDate, setEndDate] = useState(
    new Date(Date.now() + 14 * 86400000).toISOString().slice(0, 10)
  );

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim()) {
      toast.error("Please enter an Offer Title.");
      return;
    }

    const offer: ItemOffer = {
      id: `offer-${Date.now()}`,
      title: title.trim(),
      offerType,
      discountValue: parseFloat(discountValue) || 0,
      appliedCategories: selectedCategory === "all" ? categories : [selectedCategory],
      appliedProductIds: [],
      minOrderValue: parseFloat(minOrderValue) || 0,
      startDate,
      endDate,
      couponCode: couponCode.trim().toUpperCase() || undefined,
      isActive: true,
      created_at: new Date().toISOString(),
    };

    if (onSaveOffer) onSaveOffer(offer);
    toast.success(`Promotional Offer "${offer.title}" launched successfully!`);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80 backdrop-blur-sm animate-in fade-in duration-150">
      <div className="bg-card border border-border rounded-2xl shadow-2xl w-full max-w-xl sm:max-w-2xl overflow-hidden flex flex-col max-h-[92vh] animate-in zoom-in-95 duration-150">
        {/* Header */}
        <div className="px-6 py-4 border-b border-border flex items-center justify-between bg-gradient-to-r from-amber-500/10 via-orange-500/5 to-transparent">
          <div className="flex items-center gap-3">
            <div className="p-2.5 rounded-xl bg-amber-500/15 text-amber-600 dark:text-amber-400">
              <Sparkles className="w-5 h-5" />
            </div>
            <div>
              <h2 className="text-base font-bold text-foreground">Launch Promotional Offer</h2>
              <p className="text-xs text-muted-foreground">
                Set up discounts, BOGO deals, and seasonal discounts for your products
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-2 rounded-lg text-muted-foreground hover:text-foreground hover:bg-muted transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Form Body */}
        <form onSubmit={handleSubmit} className="p-6 overflow-y-auto space-y-5 text-xs">
          <div className="space-y-1.5">
            <Label htmlFor="offer-title" className="text-xs font-semibold">
              Offer / Campaign Title *
            </Label>
            <Input
              id="offer-title"
              placeholder="e.g. Weekend Mega Grocery Sale 15% OFF"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              required
            />
          </div>

          {/* Offer Type */}
          <div className="space-y-1.5">
            <Label className="text-xs font-semibold">Offer Type</Label>
            <div className="grid grid-cols-3 gap-2">
              {[
                { id: "percentage", label: "Percentage %", icon: Percent },
                { id: "flat", label: "Flat Γé╣ OFF", icon: Tag },
                { id: "bogo", label: "Buy 1 Get 1 (BOGO)", icon: Gift },
              ].map((t) => {
                const Icon = t.icon;
                return (
                  <button
                    key={t.id}
                    type="button"
                    onClick={() => setOfferType(t.id as any)}
                    className={cn(
                      "p-3 rounded-xl border text-center transition-all flex flex-col items-center gap-1.5",
                      offerType === t.id
                        ? "border-amber-500 bg-amber-500/10 text-amber-700 dark:text-amber-300 font-bold"
                        : "border-border text-muted-foreground hover:bg-muted"
                    )}
                  >
                    <Icon className="w-4 h-4" />
                    <span>{t.label}</span>
                  </button>
                );
              })}
            </div>
          </div>

          {/* Discount Value & Coupon */}
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <Label htmlFor="discount-val" className="text-xs font-semibold">
                {offerType === "percentage" ? "Discount Percentage (%)" : "Discount Amount (Γé╣)"}
              </Label>
              <Input
                id="discount-val"
                type="number"
                value={discountValue}
                onChange={(e) => setDiscountValue(e.target.value)}
                min="1"
              />
            </div>
            <div className="space-y-1.5">
              <Label htmlFor="coupon-code" className="text-xs font-semibold">
                Coupon Code
              </Label>
              <Input
                id="coupon-code"
                placeholder="e.g. SAVE10"
                value={couponCode}
                onChange={(e) => setCouponCode(e.target.value.toUpperCase())}
                className="uppercase font-mono"
              />
            </div>
          </div>

          {/* Applicable Category */}
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <Label className="text-xs font-semibold">Applicable Category</Label>
              <Select value={selectedCategory} onValueChange={setSelectedCategory}>
                <SelectTrigger>
                  <SelectValue placeholder="Select Category" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Product Categories</SelectItem>
                  {categories.map((c) => (
                    <SelectItem key={c} value={c}>
                      {c}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-1.5">
              <Label htmlFor="min-order" className="text-xs font-semibold">
                Min. Order Amount (Γé╣)
              </Label>
              <Input
                id="min-order"
                type="number"
                value={minOrderValue}
                onChange={(e) => setMinOrderValue(e.target.value)}
              />
            </div>
          </div>

          {/* Date Duration */}
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <Label htmlFor="start-date" className="text-xs font-semibold">
                Start Date
              </Label>
              <Input
                id="start-date"
                type="date"
                value={startDate}
                onChange={(e) => setStartDate(e.target.value)}
              />
            </div>
            <div className="space-y-1.5">
              <Label htmlFor="end-date" className="text-xs font-semibold">
                End Date
              </Label>
              <Input
                id="end-date"
                type="date"
                value={endDate}
                onChange={(e) => setEndDate(e.target.value)}
              />
            </div>
          </div>

          {/* Footer */}
          <div className="flex items-center justify-end gap-2 pt-4 border-t border-border">
            <Button type="button" variant="outline" size="sm" onClick={onClose}>
              Cancel
            </Button>
            <Button
              type="submit"
              size="sm"
              className="gap-1.5 bg-amber-600 hover:bg-amber-700 text-white font-bold"
            >
              <Zap className="w-4 h-4" />
              Launch Offer Now
            </Button>
          </div>
        </form>
      </div>
    </div>
  );
}

