                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        )}

        {/* Tab 2: Software Migration (Vyapar, Tally Prime, My Bill Book, Marg ERP & Busy) */}
        {activeTab === "software" && (
          <div className="flex-1 overflow-y-auto p-4 sm:p-6 space-y-5 text-xs scrollbar-thin">
