) => {
  try {
    const bankAccounts = details.accountNumber
      ? [
          {
            id: `bank_${Date.now()}`,
            bankName: details.bankName || "",
            accountNumber: details.accountNumber,
            ifsc: details.ifsc || "",
            branch: "",
            accountHolder: details.accountHolder || details.businessName,
            isDefault: true,
          },
