        open={showQuickCreate}
        onOpenChange={setShowQuickCreate}
        onActionSelect={(key) => {
          setShowQuickCreate(false);
          if (key === "sales_invoice" || key === "pos_billing") {
            setShowSalesInvoiceModal(true);
          } else if (key === "item") {
            setShowCreateItemModal(true);
          } else if (key === "party") {
            setShowCreatePartyModal(true);
          }
        }}
      />
    </div>
  );
}

