          <DialogFooter className="pt-3 border-t border-border">
            <Button onClick={handleExportCSV} className="bg-[#5046E5] text-white text-xs h-9">
              <FileSpreadsheet className="w-3.5 h-3.5 mr-1" /> Export Full Report
