  // Fetch Products & Batches from Supabase
  useEffect(() => {
    if (!orgId) return;

    const fetchProducts = async () => {
      setProductsLoading(true);
      try {
        const { data: prods, error: prodsErr } = await supabase
          .from("products")
          .select("id, barcode, name, brand, category, sku, tags, image_url")
          .eq("organization_id", orgId)
          .order("name");

        if (prodsErr) {
          console.warn("Product fetch notice:", prodsErr.message);
        }

        const productList = prods || [];
        const prodIds = productList.map((p) => p.id);

        const batchMap: Record<string, Batch[]> = {};
        if (prodIds.length > 0) {
          const { data: batches } = await supabase
            .from("product_batches")
            .select("id, product_id, batch_number, cost_price, mrp, stock, expiry_date")
            .in("product_id", prodIds);

          (batches || []).forEach((b) => {
            if (!batchMap[b.product_id]) batchMap[b.product_id] = [];
            batchMap[b.product_id].push({
              id: b.id,
              costPrice: Number(b.cost_price || 0),
              mrp: Number(b.mrp || 0),
              stock: Number(b.stock || 0),
              batchNumber: b.batch_number || "Default",
              expiryDate: b.expiry_date || undefined,
            });
          });
        }

        const mapped: Product[] = productList.map((p) => {
          const tags = (p.tags as any) || {};
          const fallbackMrp = Number(tags.mrp) || Number(tags.selling_price) || 100;
          const fallbackCost = Number(tags.purchase_price) || Number(tags.cost_price) || Math.round(fallbackMrp * 0.8);
          const fallbackStock = Number(tags.stock ?? tags.opening_stock ?? 99);

          const rawBatches = batchMap[p.id] || [];
          const pBatches: Batch[] =
            rawBatches.length > 0
              ? rawBatches.map((b) => ({
                  ...b,
                  mrp: b.mrp > 0 ? b.mrp : fallbackMrp,
                  costPrice: b.costPrice > 0 ? b.costPrice : fallbackCost,
                  stock: b.stock >= 0 ? b.stock : fallbackStock,
                }))
              : [
                  {
                    id: `gen-${p.id}`,
                    costPrice: fallbackCost,
                    mrp: fallbackMrp,
                    stock: fallbackStock,
                    batchNumber: "General",
                  },
                ];

          return {
            id: p.id,
            barcode: p.barcode || "",
            name: p.name,
            brand: p.brand || "",
            category: p.category || "General",
            batches: pBatches,
            sku: p.sku || undefined,
            tags: (p.tags as Record<string, string>) || undefined,
            imageUrl: p.image_url || undefined,
