        }
        return it;
      });
      return { ...tab, items: newItems };
    });

    setShowChangeQtyModal(false);
    toast({ title: "Quantity Updated", description: `Quantity set to ${val}` });
  };

  // Action Hotkey: Change Item Discount [D]
  const handleOpenChangeDiscount = useCallback(() => {
