  },
  {
    id: "party-ledger-statement",
    name: "Party Statement & Aging Analysis",
    category: "Transaction",
    isPro: false,
    description: "Comprehensive receivables aging, credit periods, and customer ledgers",
    tags: ["Party", "Payment Collection"],
  },
];

const FILTER_TABS = ["All", "Party", "Category", "Payment Collection", "Item", "Invoice Details", "Summary"] as const;

export default function Reports() {
  const { org, orgId } = useOrganization();
  const [searchQuery, setSearchQuery] = useState("");
  const [activeTab, setActiveTab] = useState<string>("All");
  const [showCaModal, setShowCaModal] = useState(false);
  const [selectedReport, setSelectedReport] = useState<ReportItem | null>(null);
  const [showSeeMoreTxn, setShowSeeMoreTxn] = useState(false);
  const [selectedPeriod, setSelectedPeriod] = useState<string>("current_month");

  // Document states
  const [salesDocs, setSalesDocs] = useState<BusinessDocument[]>([]);
  const [creditNotes, setCreditNotes] = useState<BusinessDocument[]>([]);
  const [purchaseDocs, setPurchaseDocs] = useState<BusinessDocument[]>([]);
  const [debitNotes, setDebitNotes] = useState<BusinessDocument[]>([]);
  const [challans, setChallans] = useState<BusinessDocument[]>([]);
  const [loading, setLoading] = useState(true);

  // CA Sharing form state
  const [caEmail, setCaEmail] = useState("");
  const [caDateRange, setCaDateRange] = useState("current_fy");
  const [caFormat, setCaFormat] = useState("all");
  const [isExporting, setIsExporting] = useState(false);

  // Load documents from service with sample data fallback
  const loadDocuments = useCallback(async () => {
    setLoading(true);
    try {
      if (!orgId) return;
      const currentOrgId = orgId;
      const [sales, cn, sr, pi, dn, dc] = await Promise.all([
        documentsService.fetchSalesDocuments(currentOrgId, "sales_invoice"),
        documentsService.fetchSalesDocuments(currentOrgId, "credit_note"),
        documentsService.fetchSalesDocuments(currentOrgId, "sales_return"),
        documentsService.fetchPurchaseDocuments(currentOrgId, "purchase_invoice"),
        documentsService.fetchPurchaseDocuments(currentOrgId, "debit_note"),
        documentsService.fetchSalesDocuments(currentOrgId, "delivery_challan"),
      ]);

      const allCredit = [...cn, ...sr];

      setSalesDocs(sales);
      setCreditNotes(allCredit);
      setPurchaseDocs(pi);
      setDebitNotes(dn);
      setChallans(dc);
    } catch (e) {
      console.warn("Failed to load documents for reports:", e);
      setSalesDocs([]);
      setCreditNotes([]);
      setPurchaseDocs([]);
      setDebitNotes([]);
      setChallans([]);
    } finally {
      setLoading(false);
    }
  }, [orgId, org?.gstin]);

  useEffect(() => {
    loadDocuments();
  }, [loadDocuments]);

  // Compute GSTR-1 and GSTR-3B Data structures
  const gstr1Data: GSTR1Data = useMemo(() => {
    const orgInfo = {
      gstin: org?.gstin || "27AAPFU0939F1ZV",
      legalName: org?.name || "CredSmart Store",
      tradeName: org?.name || "CredSmart Store",
      turnoverPrecedingFY: 5000000,
    };
    return processGSTR1Data(salesDocs, creditNotes, debitNotes, challans, orgInfo, formatFilingPeriod());
  }, [salesDocs, creditNotes, debitNotes, challans, org]);

  const gstr3bData: GSTR3BData = useMemo(() => {
    const orgInfo = {
      gstin: org?.gstin || "27AAPFU0939F1ZV",
      legalName: org?.name || "CredSmart Store",
    };
    return processGSTR3BData(salesDocs, purchaseDocs, creditNotes, debitNotes, orgInfo, formatFilingPeriod());
  }, [salesDocs, purchaseDocs, creditNotes, debitNotes, org]);

  const filteredReports = useMemo(() => {
    let reports = ALL_REPORTS;
    if (searchQuery.trim()) {
      const q = searchQuery.toLowerCase();
      reports = reports.filter(
        (r) =>
          r.name.toLowerCase().includes(q) ||
          r.description.toLowerCase().includes(q) ||
          r.tags.some((t) => t.toLowerCase().includes(q))
      );
    }
    if (activeTab !== "All") {
      reports = reports.filter((r) => r.tags.includes(activeTab) || r.category === activeTab);
    }
    return reports;
  }, [searchQuery, activeTab]);

  const favouriteReports = filteredReports.filter((r) => r.category === "Favourite");
  const gstReports = filteredReports.filter((r) => r.category === "GST");
  const txnReports = filteredReports.filter((r) => r.category === "Transaction");

  // Handler for CA Email Sharing
  const handleShareWithCa = (e: React.FormEvent) => {
    e.preventDefault();
    if (!caEmail) {
      toast.error("Please enter your CA's email address");
      return;
    }
    setIsExporting(true);
    setTimeout(() => {
      setIsExporting(false);
      setShowCaModal(false);
      toast.success(`CA Audit Package (${caFormat.toUpperCase()}) successfully sent to ${caEmail}!`);
      setCaEmail("");
    }, 1200);
  };

  // Direct 1-Click Export Handlers
  const handleDownloadGSTR1JSON = () => {
    downloadGSTR1JSON(gstr1Data);
    toast.success("GSTR-1 JSON (GST Portal Schema) downloaded successfully!");
  };

  const handleDownloadGSTR1Excel = () => {
    downloadGSTR1Excel(gstr1Data, org?.name || "CredSmart Store");
    toast.success("GSTR-1 Multi-Sheet Excel Workbook (.xls) downloaded successfully!");
  };

  const handleDownloadGSTR3BJSON = () => {
    downloadGSTR3BJSON(gstr3bData);
    toast.success("GSTR-3B JSON (Official Schema) downloaded successfully!");
  };

  const handleDownloadGSTR3BExcel = () => {
    downloadGSTR3BExcel(gstr3bData, org?.name || "CredSmart Store");
    toast.success("GSTR-3B Summary Excel (.xls) downloaded successfully!");
  };

  const handleDownloadSpecificReport = (report: ReportItem) => {
    if (report.id === "gstr-1" || report.id === "gst-sales-hsn") {
      handleDownloadGSTR1Excel();
    } else if (report.id === "gstr-3b") {
      handleDownloadGSTR3BExcel();
    } else if (report.id === "hsn-wise-sales-summary") {
      handleDownloadGSTR1Excel();
    } else {
      // General accounting report export
      downloadGSTR1Excel(gstr1Data, `${org?.name || "CredSmart"} - ${report.name}`);
      toast.success(`${report.name} Excel workbook downloaded!`);
    }
  };

  return (
    <div className="h-full flex flex-col p-3 sm:p-4 space-y-3 overflow-hidden font-sans">
      {/* Top Header with Quick Action Bar - Frosted Glass */}
      <div className="flex flex-col lg:flex-row items-start lg:items-center justify-between gap-2 border-b border-slate-200/80 dark:border-slate-800 pb-2.5 shrink-0">
        <div>
          <div className="flex items-center gap-2.5">
            <h1 className="text-xl sm:text-2xl font-black text-slate-900 dark:text-white tracking-tight font-sans">
              GST &amp; Financial Reports
            </h1>
            <span className="inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full bg-emerald-500/10 border border-emerald-500/30 text-[10px] font-mono font-bold text-emerald-600 dark:text-emerald-400">
              <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse" />
              <span>GST SCHEMA 2.0 READY</span>
            </span>
          </div>
          <p className="text-[11px] text-slate-500 dark:text-slate-400 truncate mt-0.5">
            Official GST Portal compliant GSTR-1, GSTR-3B JSON &amp; multi-sheet Excel workbooks ready for 1-click filing.
          </p>
        </div>

        {/* 1-Click Action Buttons (Horizontal scrollable on mobile) */}
        <div className="flex items-center gap-2 overflow-x-auto pb-1 scrollbar-none shrink-0 w-full sm:w-auto">
          <Button
            onClick={handleDownloadGSTR1JSON}
            variant="outline"
            size="sm"
            className="h-8 text-xs font-semibold gap-1.5 border-indigo-200 dark:border-indigo-800 bg-indigo-50/50 dark:bg-indigo-950/50 hover:bg-indigo-100 text-indigo-700 dark:text-indigo-300 rounded-xl shadow-xs px-2.5 shrink-0"
            title="Download official GST offline tool JSON for GSTR-1"
          >
            <FileCode className="w-3.5 h-3.5 text-indigo-600 dark:text-indigo-400" />
            <span>GSTR-1 JSON</span>
          </Button>

          <Button
            onClick={handleDownloadGSTR1Excel}
            variant="outline"
            size="sm"
            className="h-8 text-xs font-semibold gap-1.5 border-emerald-200 dark:border-emerald-800 bg-emerald-50/50 dark:bg-emerald-950/50 hover:bg-emerald-100 text-emerald-700 dark:text-emerald-300 rounded-xl shadow-xs px-2.5 shrink-0"
            title="Download multi-sheet GSTR-1 Excel workbook"
          >
            <FileSpreadsheet className="w-3.5 h-3.5 text-emerald-600 dark:text-emerald-400" />
            <span>GSTR-1 Excel</span>
          </Button>

          <Button
            onClick={handleDownloadGSTR3BExcel}
            variant="outline"
            size="sm"
            className="h-8 text-xs font-semibold gap-1.5 border-amber-200 dark:border-amber-800 bg-amber-50/50 dark:bg-amber-950/50 hover:bg-amber-100 text-amber-800 dark:text-amber-300 rounded-xl shadow-xs px-2.5 shrink-0"
            title="Download GSTR-3B Return Excel"
          >
            <Percent className="w-3.5 h-3.5 text-amber-600 dark:text-amber-400" />
            <span>GSTR-3B Excel</span>
          </Button>

          <button
            onClick={() => setShowCaModal(true)}
            className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl glowing-btn-amber text-white font-bold text-xs shadow-md active:scale-95 transition-all cursor-pointer shrink-0"
          >
            <div className="w-4 h-4 rounded bg-white/20 flex items-center justify-center text-[9px] font-black font-mono">
              CA
            </div>
            <span>CA 1-Click Sharing</span>
          </button>
        </div>
      </div>

      {/* GST Filing Return Period Quick Bar - Frosted Glass Card with Lightbar */}
      <div className="glass-card-3d p-2.5 sm:p-3.5 flex flex-col md:flex-row items-start md:items-center justify-between gap-2.5 shrink-0 relative overflow-hidden">
        <div className="absolute left-0 top-0 bottom-0 w-1 bg-gradient-to-b from-cyan-400 via-blue-500 to-indigo-600 rounded-l-2xl shadow-[0_0_8px_rgba(59,130,246,0.5)]" />
        <div className="flex items-center gap-2.5 min-w-0 pl-1">
          <div className="w-8 h-8 sm:w-9 sm:h-9 rounded-xl bg-indigo-500/10 border border-indigo-500/20 flex items-center justify-center text-indigo-600 dark:text-indigo-400 font-bold shrink-0">
            <Calendar className="w-4 h-4" />
          </div>
          <div className="truncate">
            <div className="flex items-center gap-1.5 sm:gap-2 flex-wrap">
              <span className="text-xs font-bold text-slate-900 dark:text-white">Return Period:</span>
              <span className="text-[10px] sm:text-[11px] font-mono font-bold text-indigo-600 dark:text-indigo-400 bg-indigo-500/10 px-1.5 py-0.2 rounded border border-indigo-500/30">
                FY {getFinancialYear()} ΓÇó {formatFilingPeriod()}
              </span>
              <span className="text-[10px] sm:text-[11px] text-slate-500 dark:text-slate-400 font-mono truncate">GSTIN: {org?.gstin || "27AAPFU0939F1ZV"}</span>
            </div>
            <p className="text-[10px] sm:text-[11px] text-slate-500 dark:text-slate-400 truncate mt-0.5">
              Active Invoices: <span className="font-bold text-slate-900 dark:text-white font-mono">{gstr1Data.summary.totalInvoicesCount}</span> ΓÇó
              Taxable: <span className="font-bold text-slate-900 dark:text-white font-mono">Γé╣{gstr1Data.summary.totalTaxableValue.toLocaleString("en-IN")}</span> ΓÇó
              Liability: <span className="font-bold text-emerald-600 dark:text-emerald-400 font-mono">Γé╣{gstr1Data.summary.totalTax.toLocaleString("en-IN")}</span>
            </p>
          </div>
        </div>

        <div className="flex items-center gap-2 self-end md:self-auto shrink-0">
          <Button
            size="sm"
            variant="ghost"
            onClick={loadDocuments}
            disabled={loading}
            className="text-xs text-slate-500 hover:text-foreground h-7 sm:h-8 gap-1.5 rounded-xl border border-slate-200/80 dark:border-slate-800 bg-white/60 dark:bg-slate-900/60"
          >
            <RefreshCw className={`w-3.5 h-3.5 ${loading ? "animate-spin" : ""}`} />
            <span>Sync Live</span>
          </Button>
        </div>
      </div>

      {/* Filter Tabs & Search Bar - Frosted Glass Container */}
      <div className="flex flex-col md:flex-row items-stretch md:items-center justify-between gap-2.5 bg-white/70 dark:bg-slate-900/70 backdrop-blur-xl p-2.5 rounded-2xl border border-slate-200/80 dark:border-slate-800 shadow-xs shrink-0">
        {/* Filter Pills (Scrollable on mobile) */}
        <div className="flex items-center gap-1.5 overflow-x-auto pb-1 scrollbar-none w-full md:w-auto">
          <span className="text-[10px] sm:text-[11px] font-bold text-slate-500 dark:text-slate-400 mr-0.5 uppercase font-mono shrink-0">Filter:</span>
          {FILTER_TABS.map((tab) => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              className={`px-2.5 py-1 sm:px-3 sm:py-1.5 rounded-xl text-xs font-bold transition-all cursor-pointer shrink-0 active:scale-95 ${
                activeTab === tab
                  ? "glowing-btn-blue text-white shadow-xs"
                  : "bg-slate-100/70 dark:bg-slate-800/60 text-slate-600 dark:text-slate-400 hover:text-foreground"
              }`}
            >
              {tab}
            </button>
          ))}
        </div>

        {/* Search Box */}
        <div className="relative w-full md:w-72">
          <Search className="w-3.5 h-3.5 absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
          <Input
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder="Find Report (e.g. GSTR-1, HSN, P&L)"
            className="pl-9 pr-14 h-9 text-xs bg-slate-50/80 dark:bg-slate-800/50 border-slate-200 dark:border-slate-700 rounded-xl"
          />
          <span className="absolute right-2.5 top-1/2 -translate-y-1/2 text-[10px] font-mono font-semibold text-slate-400 bg-slate-200/80 dark:bg-slate-700/80 px-1.5 py-0.5 rounded border border-slate-300/50 dark:border-slate-600">
            Ctrl + F
          </span>
        </div>
      </div>

      {/* Categorized 3-Column Report Grid - Scrollable Container with 3D Glass Cards */}
      <div className="flex-1 min-h-0 overflow-y-auto scrollbar-thin pr-1 pb-28">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-3.5 pb-4">
          {/* Col 1: Favourite */}
          <div className="glass-card-3d flex flex-col overflow-hidden rounded-2xl">
            <div className="flex items-center gap-2 px-4 py-3 bg-amber-500/10 border-b border-slate-200/80 dark:border-slate-800 font-bold text-xs text-amber-600 dark:text-amber-400 font-mono uppercase tracking-wider">
              <Sparkles className="w-4 h-4 text-amber-500" />
              <span>Favourite &amp; GST Returns</span>
            </div>
            <div className="divide-y divide-slate-100 dark:divide-slate-800/60 flex-1">
              {favouriteReports.length === 0 ? (
                <div className="p-6 text-center text-xs text-muted-foreground">No favourite reports matched</div>
              ) : (
                favouriteReports.map((report) => (
                  <div
                    key={report.id}
                    onClick={() => setSelectedReport(report)}
                    className="flex items-center justify-between px-4 py-3 hover:bg-indigo-50/50 dark:hover:bg-indigo-950/30 transition-colors cursor-pointer group"
                  >
                    <div className="flex-1 min-w-0 pr-2">
                      <div className="flex items-center gap-2">
                        <span className="text-xs font-semibold text-foreground group-hover:text-indigo-600 dark:group-hover:text-indigo-400 transition-colors">
                          {report.name}
                        </span>
                      </div>
                      <p className="text-[11px] text-muted-foreground truncate mt-0.5">{report.description}</p>
                    </div>
                    <div className="flex items-center gap-1.5 shrink-0">
                      <Crown className="w-3.5 h-3.5 text-amber-500" />
                      <Star className="w-3.5 h-3.5 text-amber-400 fill-amber-400" />
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>

          {/* Col 2: GST */}
          <div className="bg-white dark:bg-card rounded-xl border border-border shadow-xs flex flex-col overflow-hidden">
            <div className="flex items-center gap-2 px-4 py-3 bg-muted/40 border-b border-border font-semibold text-sm text-foreground">
              <Percent className="w-4 h-4 text-emerald-600" />
              <span>GST & Tax Compliance</span>
            </div>
            <div className="divide-y divide-border/60 flex-1">
              {gstReports.length === 0 ? (
                <div className="p-6 text-center text-xs text-muted-foreground">No GST reports matched</div>
              ) : (
                gstReports.map((report) => (
                  <div
                    key={report.id}
                    onClick={() => setSelectedReport(report)}
                    className="flex items-center justify-between px-4 py-3 hover:bg-emerald-50/50 dark:hover:bg-emerald-950/30 transition-colors cursor-pointer group"
                  >
                    <div className="flex-1 min-w-0 pr-2">
                      <div className="flex items-center gap-2">
                        <span className="text-xs font-semibold text-foreground group-hover:text-emerald-700 dark:group-hover:text-emerald-400 transition-colors">
                          {report.name}
                        </span>
                      </div>
                      <p className="text-[11px] text-muted-foreground truncate mt-0.5">{report.description}</p>
                    </div>
                    <div className="flex items-center gap-1 shrink-0">
                      <Crown className="w-3.5 h-3.5 text-amber-500" />
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>

          {/* Col 3: Transaction */}
          <div className="bg-white dark:bg-card rounded-xl border border-border shadow-xs flex flex-col overflow-hidden">
            <div className="flex items-center gap-2 px-4 py-3 bg-muted/40 border-b border-border font-semibold text-sm text-foreground">
              <Receipt className="w-4 h-4 text-blue-600" />
              <span>Transaction & P&L</span>
            </div>
            <div className="divide-y divide-border/60 flex-1">
              {txnReports.length === 0 ? (
                <div className="p-6 text-center text-xs text-muted-foreground">No transaction reports matched</div>
              ) : (
