      {/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      {/* 6. GRANULAR FEATURE ACCESS & PERMISSION TOGGLE MODAL */}
      {/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      <Dialog
        open={!!featureModalMember}
        onOpenChange={(o) => !o && setFeatureModalMember(null)}
      >
        <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto rounded-3xl p-5 sm:p-7 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 shadow-2xl space-y-5">
          {featureModalMember && (
            <>
              <DialogHeader className="border-b border-slate-100 dark:border-slate-800 pb-4">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div className="w-12 h-12 rounded-2xl bg-primary/10 text-primary font-bold text-sm flex items-center justify-center border border-primary/20">
                      {(featureModalMember.profile?.full_name || "Staff Member")
                        .split(" ")
                        .map((n) => n[0])
                        .slice(0, 2)
                        .join("")
                        .toUpperCase()}
                    </div>
                    <div>
                      <DialogTitle className="text-lg font-black text-slate-900 dark:text-white flex items-center gap-2">
                        <span>{featureModalMember.profile?.full_name || "Staff Member"}</span>
                        <span className="badge badge-info text-xs">
                          {roleLabelsMap[featureModalMember.role] || featureModalMember.role}
                        </span>
                      </DialogTitle>
                      <DialogDescription className="text-xs text-muted-foreground mt-0.5">
                        Customize individual feature switches from any role. Toggle features ON or OFF to grant or restrict access.
                      </DialogDescription>
                    </div>
                  </div>
                </div>
              </DialogHeader>

              {/* Quick Actions & Role Presets */}
              <div className="p-3.5 rounded-2xl bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 space-y-2.5">
                <div className="flex items-center justify-between">
                  <span className="text-[11px] font-bold text-slate-700 dark:text-slate-300 uppercase tracking-wider flex items-center gap-1.5">
                    <Sparkles className="w-3.5 h-3.5 text-amber-500" />
                    Quick Role Presets
                  </span>
                  <div className="flex items-center gap-2">
                    <button
                      type="button"
                      onClick={() => handleToggleAll(true)}
                      className="px-2.5 py-1 text-[11px] font-bold rounded-lg bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 hover:bg-emerald-500/20 transition-colors flex items-center gap-1 cursor-pointer"
                    >
                      <CheckCheck className="w-3 h-3" /> Enable All
                    </button>
                    <button
                      type="button"
                      onClick={() => handleToggleAll(false)}
                      className="px-2.5 py-1 text-[11px] font-bold rounded-lg bg-rose-500/10 text-rose-600 dark:text-rose-400 hover:bg-rose-500/20 transition-colors flex items-center gap-1 cursor-pointer"
                    >
                      <Power className="w-3 h-3" /> Disable All
                    </button>
                  </div>
                </div>

                <div className="flex flex-wrap items-center gap-1.5">
                  {(["salesman", "cashier", "stock_manager", "delivery_boy", "accountant", "store_owner"] as AppRole[]).map((r) => (
                    <button
                      key={r}
                      type="button"
                      onClick={() => handleApplyPreset(r)}
                      className="px-2.5 py-1 rounded-lg text-xs font-semibold bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 hover:border-primary hover:text-primary transition-all shadow-2xs cursor-pointer"
                    >
                      {roleLabelsMap[r]}
                    </button>
                  ))}
                </div>
              </div>

              {/* Feature Toggles Grid */}
              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <h4 className="text-xs font-bold text-slate-900 dark:text-white uppercase tracking-wider">
                    Feature Access Toggles
                  </h4>
                  <span className="text-xs font-bold text-primary font-mono">
                    {Object.values(editingPermissions).filter(Boolean).length} of {SYSTEM_FEATURES.length} Enabled
                  </span>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  {SYSTEM_FEATURES.map((feat) => {
                    const Icon = feat.icon;
                    const isEnabled = editingPermissions[feat.key] ?? false;

                    return (
                      <div
                        key={feat.key}
                        onClick={() => handleToggleFeature(feat.key, !isEnabled)}
                        className={cn(
                          "p-3 rounded-xl border transition-all flex items-start justify-between gap-3 cursor-pointer select-none",
                          isEnabled
                            ? "bg-primary/5 border-primary/40 shadow-xs"
                            : "bg-muted/10 border-border/70 opacity-75 hover:opacity-100"
                        )}
                      >
                        <div className="flex items-start gap-2.5 min-w-0">
                          <div
                            className={cn(
                              "p-2 rounded-lg shrink-0 mt-0.5",
                              isEnabled
                                ? "bg-primary/15 text-primary"
                                : "bg-muted text-muted-foreground"
                            )}
                          >
                            <Icon className="w-4 h-4" />
                          </div>
                          <div className="min-w-0">
                            <div className="flex items-center gap-1.5">
                              <span className="text-xs font-bold text-foreground">
                                {feat.label}
                              </span>
                            </div>
                            <p className="text-[10px] text-muted-foreground leading-tight mt-0.5">
                              {feat.description}
                            </p>
                          </div>
                        </div>

                        <div className="shrink-0 pt-0.5">
                          <Switch
                            checked={isEnabled}
                            onCheckedChange={(checked) => handleToggleFeature(feat.key, checked)}
                            onClick={(e) => e.stopPropagation()}
                          />
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>

              {/* Action Buttons */}
              <div className="flex items-center justify-end gap-2.5 pt-4 border-t border-slate-100 dark:border-slate-800">
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={() => setFeatureModalMember(null)}
                  className="text-xs cursor-pointer"
                >
                  Cancel
                </Button>
                <Button
                  type="button"
                  size="sm"
                  onClick={handleSavePermissions}
                  className="text-xs font-bold bg-primary text-primary-foreground shadow-sm cursor-pointer"
                >
                  Save &amp; Apply Feature Permissions
                </Button>
              </div>
            </>
          )}
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useState, useEffect, useCallback, useMemo } from "react";
import { usePagination } from "@/hooks/usePagination";
import { PaginationBar } from "@/components/ui/PaginationBar";
import {
  Plus,
  Search,
  Pencil,
  Trash2,
  X,
  Save,
  Users2,
  Phone,
  Mail,
  MapPin,
  Building2,
  IndianRupee,
  ArrowDownCircle,
  ArrowUpCircle,
  Truck,
  FileSpreadsheet,
  CheckCircle2,
  ShieldCheck,
  Calendar,
  ExternalLink,
  Sparkles,
  KeyRound,
} from "lucide-react";
import { lookupGSTIN, isValidGSTIN, isValidPAN, lookupTaxIdentifier } from "@/utils/gstinLookup";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { useOrganization } from "@/hooks/useOrganization";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { toast } from "sonner";
import { cn } from "@/lib/utils";
import { useNavigate, Link } from "react-router-dom";
import { ROUTE_PATHS } from "@/config/routes";
import { CompanySearchAutocomplete } from "@/components/CompanySearchAutocomplete";
import { TallyGstSearchModal } from "@/components/settings/TallyGstSearchModal";

interface Supplier {
  id: string;
  name: string;
  phone: string | null;
  email: string | null;
  gstin: string | null;
  address: string | null;
  created_at: string;
  balance: number;
  custom_fields?: any;
  customItems?: any[];
  keepSamePrice?: boolean;
  keepSameInventory?: boolean;
}

interface FormData {
  name: string;
  phone: string;
  email: string;
  gstin: string;
  address: string;
}

const emptyForm: FormData = { name: "", phone: "", email: "", gstin: "", address: "" };

export default function Suppliers() {
  const navigate = useNavigate();
  const { user } = useAuth();
  const { orgId, loading: orgLoading } = useOrganization();
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [search, setSearch] = useState("");
  const [filterType, setFilterType] = useState<"all" | "gst" | "credit">("all");
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [form, setForm] = useState<FormData>(emptyForm);
  const [saving, setSaving] = useState(false);
  const [deleteConfirm, setDeleteConfirm] = useState<string | null>(null);
  const [isLookingUpGst, setIsLookingUpGst] = useState(false);
  const [gstLookupSuccess, setGstLookupSuccess] = useState<string | null>(null);
  const [tallyModalOpen, setTallyModalOpen] = useState(false);

  // Credit modal
  const [creditModal, setCreditModal] = useState<{ supplierId: string; name: string } | null>(null);
  const [creditAmount, setCreditAmount] = useState("");
  const [creditDesc, setCreditDesc] = useState("");
  const [creditType, setCreditType] = useState<"credit" | "payment">("credit");
  type CreditHistoryEntry = {
    id: string;
    amount: number | string | null;
    type: "credit" | "payment";
    description: string | null;
    created_at: string;
  };
  const [creditHistory, setCreditHistory] = useState<CreditHistoryEntry[]>([]);

  const triggerGstAutoFill = async (targetId: string, showToast = true) => {
    const clean = targetId.trim().toUpperCase();
    if (!clean) {
      if (showToast) toast.error("Please enter a valid 15-character GSTIN or 10-character PAN.");
      return;
    }
    if (!isValidGSTIN(clean) && !isValidPAN(clean)) {
      if (showToast) toast.error("Invalid format. Expected 15-char GSTIN (e.g. 24AABCA1234F1ZA) or 10-char PAN (e.g. AABCA1234F)");
      return;
    }

    setIsLookingUpGst(true);
    setGstLookupSuccess(null);
    try {
      const result = await lookupTaxIdentifier(clean);
      setForm((prev) => ({
        ...prev,
        name: result.legalName || prev.name,
        address: result.address || prev.address,
        phone: result.phone || prev.phone,
        email: result.email || prev.email,
        gstin: result.gstin || clean,
      }));

      if (result.legalName) {
        setGstLookupSuccess(`Verified: ${result.legalName} ΓÇó ${result.state} (Active)`);
        if (showToast) {
          toast.success(`Verified details auto-filled for ${result.legalName}!`);
        }
      } else {
        setGstLookupSuccess(`State: ${result.state} ΓÇó PAN: ${result.pan} (${result.category})`);
        if (showToast) {
          toast.info(`State: ${result.state} ΓÇó PAN: ${result.pan} detected`);
        }
      }
    } catch (err: unknown) {
      if (showToast) {
        const message = err instanceof Error ? err.message : typeof err === "string" ? err : "Failed to fetch tax details.";
        toast.error(message);
      }
    } finally {
      setIsLookingUpGst(false);
    }
  };

  const handleGstinChange = (value: string) => {
    const clean = value.toUpperCase().replace(/[^0-9A-Z]/g, "").slice(0, 15);
    setForm((prev) => ({ ...prev, gstin: clean }));

    if (clean.length === 10 && isValidPAN(clean)) {
      triggerGstAutoFill(clean, false);
    } else if (clean.length === 15 && isValidGSTIN(clean)) {
      triggerGstAutoFill(clean, false);
    } else if (clean.length < 10) {
      setGstLookupSuccess(null);
    }
  };

  const fetchSuppliers = useCallback(async () => {
    if (!orgId) {
      setSuppliers([]);
      setLoading(false);
      return;
    }
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from("suppliers")
        .select("id, name, phone, email, gstin, address, created_at, custom_fields")
        .eq("organization_id", orgId)
        .order("name");

      if (error) {
        console.error("fetchSuppliers error:", error);
        setSuppliers([]);
        setLoading(false);
        return;
      }

      const { data: credits, error: creditsError } = await supabase
        .from("credit_transactions")
        .select("party_id, amount, type")
        .eq("organization_id", orgId)
        .eq("party_type", "supplier");

      if (creditsError) {
        console.error("fetchSuppliers credits error:", creditsError);
      }

      const balanceMap: Record<string, number> = {};
      (credits || []).forEach((c) => {
        if (!balanceMap[c.party_id]) balanceMap[c.party_id] = 0;
        balanceMap[c.party_id] += c.type === "credit" ? Number(c.amount || 0) : -Number(c.amount || 0);
      });

      if (data) {
        setSuppliers(
          data.map((s: any) => {
            let cf = s.custom_fields;
            if (typeof cf === "string") {
              try {
                cf = JSON.parse(cf);
              } catch {
                cf = {};
              }
            }
            if (!cf || typeof cf !== "object") cf = {};
            const customItems = Array.isArray(cf.customItems)
              ? cf.customItems
              : Array.isArray(cf.custom_items)
              ? cf.custom_items
              : [];
            const keepSamePrice = cf.keepSamePrice !== false && cf.keep_same_price !== false;
            const keepSameInventory = cf.keepSameInventory !== false && cf.keep_same_inventory !== false;

            return {
              ...s,
              balance: balanceMap[s.id] || 0,
              custom_fields: cf,
              customItems,
              keepSamePrice,
              keepSameInventory,
            };
          })
        );
      }
    } catch (err) {
      console.error("fetchSuppliers unexpected error:", err);
      setSuppliers([]);
    } finally {
      setLoading(false);
    }
  }, [orgId]);

  useEffect(() => {
    if (orgLoading) return;
    fetchSuppliers();
  }, [fetchSuppliers, orgLoading]);

  const filtered = useMemo(() => {
    return suppliers.filter((s) => {
      const matchSearch =
        !search ||
        s.name.toLowerCase().includes(search.toLowerCase()) ||
        (s.phone && s.phone.includes(search)) ||
        (s.gstin && s.gstin.toLowerCase().includes(search.toLowerCase())) ||
        (s.email && s.email.toLowerCase().includes(search.toLowerCase()));

      const matchFilter =
        filterType === "all" ||
        (filterType === "gst" && s.gstin && s.gstin.trim().length > 0) ||
        (filterType === "credit" && s.balance > 0);

      return matchSearch && matchFilter;
    });
  }, [suppliers, search, filterType]);

  const {
    page,
    setPage,
    pageSize,
    setPageSize,
    paginatedItems,
    totalPages,
    totalItems,
    startIndex,
    endIndex,
    hasNext,
    hasPrev,
  } = usePagination(filtered, 25);

  const gstinSuppliersCount = useMemo(() => {
    return suppliers.filter((s) => s.gstin && s.gstin.trim().length > 0).length;
  }, [suppliers]);

  const totalCreditPayables = useMemo(() => {
    return suppliers.reduce((s, sup) => s + Math.max(sup.balance, 0), 0);
  }, [suppliers]);

  const openCreate = () => {
    setEditingId(null);
    setForm(emptyForm);
    setShowForm(true);
  };

  const openEdit = (s: Supplier) => {
    setEditingId(s.id);
    setForm({
      name: s.name,
      phone: s.phone || "",
      email: s.email || "",
      gstin: s.gstin || "",
      address: s.address || "",
    });
    setShowForm(true);
  };

  const handleQuickPurchase = (s: Supplier) => {
    navigate(ROUTE_PATHS.purchases, {
      state: {
        openForm: true,
        supplierId: s.id,
        supplierName: s.name,
      },
    });
  };

  const handleSave = async () => {
    const nameTrimmed = form.name.trim();
    if (!nameTrimmed) {
      toast.error("Supplier name is required");
      return;
    }

    const gstinTrimmed = form.gstin.trim().toUpperCase();
    if (gstinTrimmed) {
      const gstinRegex = /^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z]{1}[1-9A-Z]{1}Z[0-9A-Z]{1}$/;
      if (!gstinRegex.test(gstinTrimmed)) {
        toast.error("Invalid GSTIN format. Expected 15 characters (e.g. 29AAAAA0000A1Z5)");
        return;
      }
    }

    const emailTrimmed = form.email.trim();
    if (emailTrimmed && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(emailTrimmed)) {
      toast.error("Please enter a valid email address");
      return;
    }

    if (!orgId) return;
    setSaving(true);
    try {
      if (editingId) {
        const { error } = await supabase
          .from("suppliers")
          .update({
            name: nameTrimmed,
            phone: form.phone.trim(),
            email: emailTrimmed,
            gstin: gstinTrimmed,
            address: form.address.trim(),
          })
          .eq("id", editingId);
        if (error) throw error;
        toast.success("Supplier updated successfully");
      } else {
        const { error } = await supabase.from("suppliers").insert({
          organization_id: orgId,
          name: nameTrimmed,
          phone: form.phone.trim(),
          email: emailTrimmed,
          gstin: gstinTrimmed,
          address: form.address.trim(),
        });
        if (error) throw error;
        toast.success("Supplier created successfully");
      }
      setShowForm(false);
      fetchSuppliers();
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : typeof err === "string" ? err : "Failed to save supplier";
      toast.error(message);
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (id: string) => {
    try {
      const { error } = await supabase.from("suppliers").delete().eq("id", id);
      if (error) {
        toast.error(
          error.message.includes("violates foreign key")
            ? "Cannot delete ΓÇö supplier has linked invoices/purchases"
            : error.message
        );
      } else {
        toast.success("Supplier deleted");
        fetchSuppliers();
      }
    } catch (err: unknown) {
      console.error("handleDelete error:", err);
      const message = err instanceof Error ? err.message : typeof err === "string" ? err : "Failed to delete";
      toast.error(message);
    }
    setDeleteConfirm(null);
  };

  const openCreditModal = async (s: Supplier) => {
    setCreditModal({ supplierId: s.id, name: s.name });
    setCreditAmount("");
    setCreditDesc("");
    setCreditType("credit");
    try {
      const { data, error } = await supabase
        .from("credit_transactions")
        .select("id, amount, type, description, created_at")
        .eq("party_id", s.id)
        .eq("party_type", "supplier")
        .order("created_at", { ascending: false })
        .limit(20);
      if (error) {
        console.error("openCreditModal error:", error);
        setCreditHistory([]);
      } else {
        setCreditHistory(data || []);
      }
    } catch (err) {
      console.error("openCreditModal unexpected error:", err);
      setCreditHistory([]);
    }
  };

  const handleCreditSubmit = async () => {
    const amt = parseFloat(creditAmount);
    if (!amt || amt <= 0) {
      toast.error("Enter a valid amount");
      return;
    }
    if (!orgId || !user || !creditModal) return;
    try {
      const { error } = await supabase.from("credit_transactions").insert({
        organization_id: orgId,
        party_type: "supplier",
        party_id: creditModal.supplierId,
        amount: amt,
        type: creditType,
        description: creditDesc,
        created_by: user.id,
      });
      if (error) {
        toast.error(error.message);
        return;
      }
      toast.success(creditType === "credit" ? "Credit recorded" : "Payment recorded");
      setCreditModal(null);
      fetchSuppliers();
    } catch (err: unknown) {
      console.error("handleCreditSubmit error:", err);
      const message = err instanceof Error ? err.message : typeof err === "string" ? err : "Failed to save credit transaction";
      toast.error(message);
    }
  };

  if (orgLoading || loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="w-8 h-8 border-2 border-primary border-t-transparent rounded-full animate-spin" />
      </div>
    );
  }

  return (
    <div className="w-full max-w-[1400px] mx-auto px-4 py-6 sm:px-8 sm:py-8 space-y-6 font-sans">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <div className="flex items-center gap-2.5">
            <h1 className="text-2xl sm:text-3xl font-black tracking-tight text-slate-900 dark:text-white font-sans flex items-center gap-2.5">
              <Truck className="w-7 h-7 text-indigo-600 dark:text-indigo-400" />
              Suppliers &amp; Vendors
            </h1>
            <span className="inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full bg-amber-500/10 border border-amber-500/30 text-[10px] font-mono font-bold text-amber-600 dark:text-amber-400">
              <span className="w-1.5 h-1.5 rounded-full bg-amber-500 animate-pulse" />
              <span>PROCUREMENT HUB</span>
            </span>
          </div>
          <p className="text-sm text-slate-500 dark:text-slate-400 mt-1">
            Manage your procurement directory, GSTIN numbers, and supplier payables
          </p>
        </div>
        <div className="flex items-center gap-2 self-start sm:self-auto flex-wrap">
          <Button
            asChild
            variant="outline"
            className="gap-1.5 font-bold bg-emerald-500/10 hover:bg-emerald-500/20 text-emerald-600 dark:text-emerald-400 border-emerald-500/30 rounded-xl text-xs h-9 shadow-xs"
          >
            <Link to={`${ROUTE_PATHS.parties}?bulk=1`}>
              <FileSpreadsheet className="w-4 h-4 text-emerald-600 dark:text-emerald-400" />
              <span>Bulk Import</span>
            </Link>
          </Button>
          <Button
