    navigate(ROUTE_PATHS.purchases, {
      state: {
        openForm: true,
        prefilledSupplier: {
          name: comp.company_name,
          phone: comp.phone_number || "",
          address: comp.company_address || "",
          gstin: comp.cin || "",
