      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
        {loading ? (
          [...Array(6)].map((_, i) => (
            <div
              key={i}
              className="h-52 glass-card-3d rounded-2xl p-5 shadow-sm space-y-3 animate-pulse"
