      buildXmlCell("Invoice Value", true),
      buildXmlCell("Place Of Supply", true),
      buildXmlCell("Rate (%)", true),
      buildXmlCell("Taxable Value (Γé╣)", true),
      buildXmlCell("Integrated Tax (Γé╣)", true),
      buildXmlCell("Cess (Γé╣)", true),
    ]),
  ];
  data.b2cl.forEach((grp) => {
    grp.inv.forEach((inv) => {
